(1,'{\"fa\":\"\\u0647\\u0631 \\u0631\\u0648\\u0632 \\u0641\\u0631\\u0635\\u062a\\u06cc \\u062a\\u0627\\u0632\\u0647 \\u0628\\u0631\\u0627\\u06cc \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u062e\\u0648\\u062f\\u062a \\u0627\\u0633\\u062a.\",\"en\":\"Every day is a fresh chance to care for yourself.\"}',NULL,1,1,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(2,'{\"fa\":\"\\u0628\\u062f\\u0646 \\u0645\\u0646 \\u0634\\u0627\\u06cc\\u0633\\u062a\\u0647\\u200c\\u06cc \\u0645\\u0647\\u0631\\u0628\\u0627\\u0646\\u06cc \\u0648 \\u0627\\u062d\\u062a\\u0631\\u0627\\u0645 \\u0627\\u0633\\u062a.\",\"en\":\"My body deserves kindness and respect.\"}',NULL,1,2,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(3,'{\"fa\":\"\\u0645\\u0646 \\u0628\\u0647 \\u0631\\u06cc\\u062a\\u0645 \\u0628\\u062f\\u0646\\u0645 \\u06af\\u0648\\u0634 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u0645 \\u0648 \\u0622\\u0646 \\u0631\\u0627 \\u0645\\u06cc\\u200c\\u067e\\u0630\\u06cc\\u0631\\u0645.\",\"en\":\"I listen to and honor my body\\u2019s rhythm.\"}',NULL,1,3,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(4,'{\"fa\":\"\\u0622\\u0631\\u0627\\u0645\\u0634 \\u0645\\u0646 \\u0627\\u0632 \\u062f\\u0631\\u0648\\u0646 \\u0634\\u0631\\u0648\\u0639 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"My calm begins within.\"}',NULL,1,4,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(5,'{\"fa\":\"\\u0645\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06a9\\u0627\\u0641\\u06cc \\u0647\\u0633\\u062a\\u0645\\u060c \\u0647\\u0645\\u06cc\\u0646 \\u062d\\u0627\\u0644\\u0627.\",\"en\":\"I am enough, just as I am.\"}',NULL,1,5,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(6,'{\"fa\":\"\\u0628\\u0627 \\u0647\\u0631 \\u0646\\u0641\\u0633\\u060c \\u0627\\u0646\\u0631\\u0698\\u06cc \\u062a\\u0627\\u0632\\u0647\\u200c\\u0627\\u06cc \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u0645.\",\"en\":\"With every breath, I welcome fresh energy.\"}',NULL,1,6,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(7,'{\"fa\":\"\\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u062e\\u0648\\u062f\\u0645 \\u06cc\\u06a9 \\u0627\\u0646\\u062a\\u062e\\u0627\\u0628 \\u0642\\u062f\\u0631\\u062a\\u0645\\u0646\\u062f \\u0627\\u0633\\u062a.\",\"en\":\"Caring for myself is a powerful choice.\"}',NULL,1,7,'2026-09-23 09:00:00','2026-09-23 09:00:00');
