INSERT INTO `articles` VALUES
(1,'period-blood-clots','{\"fa\":\"\\u0644\\u062e\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062e\\u0648\\u0646 \\u062f\\u0631 \\u062f\\u0648\\u0631\\u0627\\u0646 \\u067e\\u0631\\u06cc\\u0648\\u062f\\u061b \\u0645\\u0639\\u0646\\u06cc \\u0622\\u0646 \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"en\":\"Blood clots during your period: what do they mean?\"}','{\"fa\":\"\\u0644\\u062e\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062e\\u0648\\u0646 \\u062f\\u0631 \\u067e\\u0631\\u06cc\\u0648\\u062f \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0637\\u0628\\u06cc\\u0639\\u06cc\\u200c\\u0627\\u0646\\u062f\\u061b \\u0627\\u0645\\u0627 \\u0686\\u0647 \\u0632\\u0645\\u0627\\u0646\\u06cc \\u0628\\u0627\\u06cc\\u062f \\u0646\\u06af\\u0631\\u0627\\u0646 \\u0634\\u062f\\u061f\",\"en\":\"Period clots are usually normal \\u2014 but when should you worry?\"}',NULL,'[\"menstruation\"]','period_health',4,NULL,NULL,1,'2026-09-23 09:00:00',1,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(2,'period-pain-relief','{\"fa\":\"\\u0631\\u0627\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0627\\u0647\\u0634 \\u062f\\u0631\\u062f \\u067e\\u0631\\u06cc\\u0648\\u062f\",\"en\":\"Ways to relieve period pain\"}','{\"fa\":\"\\u0627\\u0632 \\u06af\\u0631\\u0645\\u0627 \\u062f\\u0631\\u0645\\u0627\\u0646\\u06cc \\u062a\\u0627 \\u062a\\u063a\\u0630\\u06cc\\u0647\\u061b \\u0631\\u0648\\u0634\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0624\\u062b\\u0631 \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0627\\u0647\\u0634 \\u062f\\u0631\\u062f\\u0647\\u0627\\u06cc \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc\",\"en\":\"From heat therapy to nutrition: effective ways to ease cramps\"}',NULL,'[\"menstruation\"]','period_health',5,NULL,NULL,1,'2026-09-23 09:00:00',2,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(3,'follicular-energy','{\"fa\":\"\\u0641\\u0627\\u0632 \\u0641\\u0648\\u0644\\u06cc\\u06a9\\u0648\\u0644\\u0627\\u0631\\u061b \\u0632\\u0645\\u0627\\u0646 \\u0627\\u0648\\u062c \\u0627\\u0646\\u0631\\u0698\\u06cc\",\"en\":\"The follicular phase: your energy peak\"}','{\"fa\":\"\\u0686\\u0631\\u0627 \\u0628\\u0639\\u062f \\u0627\\u0632 \\u067e\\u0631\\u06cc\\u0648\\u062f \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0631\\u06cc \\u0648 \\u0686\\u0637\\u0648\\u0631 \\u0627\\u0632 \\u0622\\u0646 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\",\"en\":\"Why you feel more energetic after your period and how to use it\"}',NULL,'[\"follicular\"]','cycle_science',3,NULL,NULL,1,'2026-09-23 09:00:00',1,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(4,'ovulation-signs','{\"fa\":\"\\u0646\\u0634\\u0627\\u0646\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u0628\\u0634\\u0646\\u0627\\u0633\",\"en\":\"Know the signs of ovulation\"}','{\"fa\":\"\\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u062a\\u0631\\u0634\\u062d\\u0627\\u062a\\u060c \\u062f\\u0645\\u0627\\u06cc \\u0628\\u062f\\u0646 \\u0648 \\u0639\\u0644\\u0627\\u0626\\u0645\\u06cc \\u06a9\\u0647 \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u0646\\u0634\\u0627\\u0646 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u0646\\u062f\",\"en\":\"Discharge changes, body temperature and signs that signal ovulation\"}',NULL,'[\"ovulation\"]','fertility',4,NULL,NULL,1,'2026-09-23 09:00:00',1,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(5,'pms-management','{\"fa\":\"\\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u0639\\u0644\\u0627\\u0626\\u0645 \\u067e\\u06cc\\u200c\\u0627\\u0645\\u200c\\u0627\\u0633\",\"en\":\"Managing PMS symptoms\"}','{\"fa\":\"\\u0631\\u0627\\u0647\\u06a9\\u0627\\u0631\\u0647\\u0627\\u06cc\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u062e\\u0644\\u0642\\u06cc \\u0648 \\u0639\\u0644\\u0627\\u0626\\u0645 \\u062c\\u0633\\u0645\\u06cc \\u067e\\u06cc\\u0634 \\u0627\\u0632 \\u067e\\u0631\\u06cc\\u0648\\u062f\",\"en\":\"Strategies to manage mood and physical symptoms before your period\"}',NULL,'[\"luteal\"]','wellbeing',5,NULL,NULL,1,'2026-09-23 09:00:00',1,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(6,'cycle-nutrition-basics','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0645\\u062a\\u0646\\u0627\\u0633\\u0628 \\u0628\\u0627 \\u0686\\u0631\\u062e\\u0647 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc\",\"en\":\"Eating in sync with your cycle\"}','{\"fa\":\"\\u062f\\u0631 \\u0647\\u0631 \\u0641\\u0627\\u0632 \\u0686\\u0647 \\u0628\\u062e\\u0648\\u0631\\u06cc\\u0645 \\u062a\\u0627 \\u062d\\u0627\\u0644 \\u0628\\u0647\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u0645\",\"en\":\"What to eat in each phase to feel your best\"}',NULL,NULL,'nutrition',6,NULL,NULL,1,'2026-09-23 09:00:00',1,'2026-09-23 09:00:00','2026-09-23 09:00:00');
