INSERT INTO `catalog_items` VALUES
(1,'pelvic_levels','level_1',1,1,NULL,'{\"fa\":\"سطح ۱\",\"en\":\"Level 1\"}','{\"fa\":\"عضلاتی را منقبض کن که با آن جلوی ادرار را می‌گیری. شکم، باسن و ران‌ها شل بمانند و نفست را حبس نکن.\",\"en\":\"Squeeze the muscles you use to stop the flow of urine. Keep your belly, buttocks and thighs relaxed and don\'t hold your breath.\"}','{\"week_from\":1,\"hold_sec\":3,\"rest_sec\":3,\"reps\":10,\"sets\":3}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(2,'pelvic_levels','level_2',2,1,NULL,'{\"fa\":\"سطح ۲\",\"en\":\"Level 2\"}','{\"fa\":\"عضلاتی را منقبض کن که با آن جلوی ادرار را می‌گیری. شکم، باسن و ران‌ها شل بمانند و نفست را حبس نکن.\",\"en\":\"Squeeze the muscles you use to stop the flow of urine. Keep your belly, buttocks and thighs relaxed and don\'t hold your breath.\"}','{\"week_from\":3,\"hold_sec\":5,\"rest_sec\":5,\"reps\":10,\"sets\":3}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(3,'pelvic_levels','level_3',3,1,NULL,'{\"fa\":\"سطح ۳\",\"en\":\"Level 3\"}','{\"fa\":\"عضلاتی را منقبض کن که با آن جلوی ادرار را می‌گیری. شکم، باسن و ران‌ها شل بمانند و نفست را حبس نکن.\",\"en\":\"Squeeze the muscles you use to stop the flow of urine. Keep your belly, buttocks and thighs relaxed and don\'t hold your breath.\"}','{\"week_from\":5,\"hold_sec\":8,\"rest_sec\":8,\"reps\":10,\"sets\":3}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(4,'pelvic_levels','level_4',4,1,NULL,'{\"fa\":\"سطح ۴\",\"en\":\"Level 4\"}','{\"fa\":\"عضلاتی را منقبض کن که با آن جلوی ادرار را می‌گیری. شکم، باسن و ران‌ها شل بمانند و نفست را حبس نکن.\",\"en\":\"Squeeze the muscles you use to stop the flow of urine. Keep your belly, buttocks and thighs relaxed and don\'t hold your breath.\"}','{\"week_from\":7,\"hold_sec\":10,\"rest_sec\":10,\"reps\":10,\"sets\":3}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(5,'pelvic_alerts','uti_warning',1,1,NULL,'{\"fa\":\"اگر تب، لرز یا درد پهلو داری، زودتر به پزشک مراجعه کن.\",\"en\":\"If you have a fever, chills or pain in your side, see a doctor soon.\"}',NULL,'{\"severity\":\"urgent\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(6,'pelvic_alerts','program_suitability',2,1,NULL,'{\"fa\":\"مناسب بعد از زایمان، یائسگی و هر وقت نشت ادرار داری. اگر درد لگن یا سنگینی داری، اول با پزشک یا فیزیوتراپ لگن مشورت کن.\",\"en\":\"Suited to after childbirth, menopause and any time you leak urine. If you have pelvic pain or heaviness, talk to a doctor or pelvic physiotherapist first.\"}',NULL,'{\"severity\":\"info\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(7,'missed_pill_rules','combined_one',1,1,NULL,'{\"fa\":\"۱ قرص (کمتر از ۴۸ ساعت دیر)\",\"en\":\"1 pill (less than 48 hours late)\"}','{\"fa\":\"این راهنمای عمومی قرص ترکیبی است. در صورت شک با پزشک یا داروساز صحبت کن.\",\"en\":\"This is general guidance for the combined pill. If in doubt, talk to a doctor or pharmacist.\"}','{\"methods\":[\"combined_pill\"],\"missed\":1,\"severity\":\"caution\",\"steps\":[{\"fa\":\"قرص جاافتاده را همین حالا بخور، حتی اگر یعنی امروز دو قرص بخوری.\",\"en\":\"Take the missed pill now, even if it means taking two pills today.\"},{\"fa\":\"بقیه قرص‌ها را طبق معمول ادامه بده.\",\"en\":\"Carry on with the rest of the pack as usual.\"}]}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(8,'missed_pill_rules','combined_two_plus',2,1,NULL,'{\"fa\":\"۲ قرص یا بیشتر\",\"en\":\"2 or more pills\"}','{\"fa\":\"این راهنمای عمومی قرص ترکیبی است. در صورت شک با پزشک یا داروساز صحبت کن.\",\"en\":\"This is general guidance for the combined pill. If in doubt, talk to a doctor or pharmacist.\"}','{\"methods\":[\"combined_pill\"],\"missed\":2,\"severity\":\"caution\",\"steps\":[{\"fa\":\"آخرین قرص جاافتاده را همین حالا بخور، حتی اگر یعنی امروز دو قرص بخوری.\",\"en\":\"Take the last missed pill now, even if it means taking two pills today.\"},{\"fa\":\"بقیه قرص‌ها را طبق معمول ادامه بده.\",\"en\":\"Carry on with the rest of the pack as usual.\"},{\"fa\":\"تا ۷ روز پشت سر هم قرص نخورده‌ای، از کاندوم استفاده کن.\",\"en\":\"Use condoms until you have taken 7 pills in a row.\"},{\"fa\":\"اگر در ۷ روز آخر قرص‌های فعال هستی، بعد از تمام شدنشان روزهای استراحت را حذف کن و بسته بعد را مستقیم شروع کن.\",\"en\":\"If you are in the last 7 active pills, skip the break after them and start the next pack straight away.\"}]}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(9,'missed_pill_rules','week1_unprotected',3,1,NULL,'{\"fa\":\"اگر در هفته اول بسته رابطه محافظت‌نشده داشتی\",\"en\":\"If you had unprotected sex in the first week of the pack\"}','{\"fa\":\"ممکن است به پیشگیری اضطراری نیاز داشته باشی. هر چه زودتر با پزشک یا داروساز مشورت کن.\",\"en\":\"You may need emergency contraception. Talk to a doctor or pharmacist as soon as possible.\"}','{\"methods\":[\"combined_pill\"],\"severity\":\"urgent\",\"pack_week\":1}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(10,'missed_pill_rules','progestin_note',4,1,NULL,'{\"fa\":\"قرص تک‌هورمونی\",\"en\":\"Progestogen-only pill\"}','{\"fa\":\"برای قرص تک‌هورمونی قواعد فرق دارد و به نوع قرص بستگی دارد؛ در صورت شک با پزشک یا داروساز صحبت کن.\",\"en\":\"The rules differ for the progestogen-only pill and depend on the type of pill; if in doubt, talk to a doctor or pharmacist.\"}','{\"methods\":[\"progestin_pill\"],\"severity\":\"caution\",\"steps\":[{\"fa\":\"قرص جاافتاده را به محض یادآوری بخور و قرص بعدی را سر ساعت همیشگی بخور.\",\"en\":\"Take the missed pill as soon as you remember and the next one at the usual time.\"},{\"fa\":\"اگر بیشتر از زمان مجاز نوع قرصت دیر کردی، تا ۲ روز از کاندوم استفاده کن.\",\"en\":\"If you are later than your pill type allows, use condoms for the next 2 days.\"}]}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00');
/*!40000 ALTER TABLE `catalog_items` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `challenges`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `challenges` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(255) DEFAULT NULL,
  `title` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`title`)),
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`description`)),
  `cycle_day_from` tinyint(3) unsigned DEFAULT NULL,
  `cycle_day_to` tinyint(3) unsigned DEFAULT NULL,
  `category` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `challenges_slug_unique` (`slug`),
  KEY `challenges_active_day_index` (`is_active`,`cycle_day_from`,`cycle_day_to`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `challenges` WRITE;
/*!40000 ALTER TABLE `challenges` DISABLE KEYS */;
INSERT INTO `challenges` VALUES
(1,'log-basal-temperature','{\"fa\":\"\\u062b\\u0628\\u062a \\u062f\\u0645\\u0627\\u06cc \\u0628\\u062f\\u0646\",\"en\":\"Log your body temperature\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u062f\\u0645\\u0627\\u06cc \\u067e\\u0627\\u06cc\\u0647 \\u0628\\u062f\\u0646\\u062a \\u0631\\u0627 \\u062b\\u0628\\u062a \\u06a9\\u0646 \\u062a\\u0627 \\u0631\\u0648\\u0646\\u062f \\u0633\\u06cc\\u06a9\\u0644 \\u062f\\u0642\\u06cc\\u0642\\u200c\\u062a\\u0631 \\u0634\\u0648\\u062f\",\"en\":\"Log your basal body temperature today for a more accurate cycle\"}',NULL,NULL,'tracking',1,1,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(2,'log-mood','{\"fa\":\"\\u062d\\u0627\\u0644 \\u0627\\u0645\\u0631\\u0648\\u0632\\u062a \\u0631\\u0627 \\u062b\\u0628\\u062a \\u06a9\\u0646\",\"en\":\"Log how you feel today\"}','{\"fa\":\"\\u06cc\\u06a9 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u0648\\u0642\\u062a \\u0628\\u06af\\u0630\\u0627\\u0631 \\u0648 \\u062d\\u0627\\u0644 \\u0648 \\u062d\\u0648\\u0635\\u0644\\u0647\\u200c\\u06cc \\u0627\\u0645\\u0631\\u0648\\u0632\\u062a \\u0631\\u0627 \\u062b\\u0628\\u062a \\u06a9\\u0646\",\"en\":\"Take a minute to log today\'s mood\"}',NULL,NULL,'tracking',1,2,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(3,'log-symptoms','{\"fa\":\"\\u0639\\u0644\\u0627\\u0626\\u0645 \\u0627\\u0645\\u0631\\u0648\\u0632 \\u0631\\u0627 \\u06a9\\u0627\\u0645\\u0644 \\u06a9\\u0646\",\"en\":\"Complete today\'s symptoms\"}','{\"fa\":\"\\u0639\\u0644\\u0627\\u0626\\u0645 \\u0627\\u0645\\u0631\\u0648\\u0632\\u062a \\u0631\\u0627 \\u062b\\u0628\\u062a \\u06a9\\u0646 \\u062a\\u0627 \\u0627\\u0644\\u06af\\u0648\\u0647\\u0627\\u06cc \\u0628\\u062f\\u0646\\u062a \\u0648\\u0627\\u0636\\u062d\\u200c\\u062a\\u0631 \\u0634\\u0648\\u062f\",\"en\":\"Log today\'s symptoms so your patterns become clearer\"}',NULL,NULL,'tracking',1,3,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(4,'log-seven-days','{\"fa\":\"\\u0647\\u0641\\u062a \\u0631\\u0648\\u0632 \\u067e\\u06cc\\u0627\\u067e\\u06cc \\u062b\\u0628\\u062a \\u06a9\\u0646\",\"en\":\"Log seven days in a row\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u0647\\u0645 \\u062b\\u0628\\u062a \\u06a9\\u0646 \\u062a\\u0627 \\u0632\\u0646\\u062c\\u06cc\\u0631\\u0647\\u200c\\u06cc \\u0647\\u0641\\u062a\\u200c\\u0631\\u0648\\u0632\\u0647\\u200c\\u0627\\u062a \\u06a9\\u0627\\u0645\\u0644 \\u0634\\u0648\\u062f\",\"en\":\"Log today to complete your seven-day run\"}',NULL,NULL,'tracking',1,4,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(5,'meditate-10-minutes','{\"fa\":\"\\u06f1\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u0645\\u062f\\u06cc\\u062a\\u06cc\\u0634\\u0646\",\"en\":\"10 minutes of meditation\"}','{\"fa\":\"\\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0627\\u0647\\u0634 \\u0627\\u0633\\u062a\\u0631\\u0633\\u060c \\u06f1\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u0645\\u062f\\u06cc\\u062a\\u06cc\\u0634\\u0646 \\u06a9\\u0646\",\"en\":\"Meditate for 10 minutes to reduce stress\"}',NULL,NULL,'mindfulness',1,5,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(6,'deep-breathing','{\"fa\":\"\\u067e\\u0646\\u062c \\u0646\\u0641\\u0633 \\u0639\\u0645\\u06cc\\u0642\",\"en\":\"Five deep breaths\"}','{\"fa\":\"\\u0647\\u0631 \\u0648\\u0642\\u062a \\u0641\\u0634\\u0627\\u0631 \\u0631\\u0627 \\u062d\\u0633 \\u06a9\\u0631\\u062f\\u06cc\\u060c \\u067e\\u0646\\u062c \\u0646\\u0641\\u0633 \\u0639\\u0645\\u06cc\\u0642 \\u0648 \\u0622\\u0631\\u0627\\u0645 \\u0628\\u06a9\\u0634\",\"en\":\"Take five slow, deep breaths whenever tension builds\"}',NULL,NULL,'mindfulness',1,6,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(7,'gratitude-note','{\"fa\":\"\\u0633\\u0647 \\u0686\\u06cc\\u0632 \\u062e\\u0648\\u0628 \\u0627\\u0645\\u0631\\u0648\\u0632\",\"en\":\"Three good things\"}','{\"fa\":\"\\u0633\\u0647 \\u0686\\u06cc\\u0632 \\u06a9\\u0647 \\u0627\\u0645\\u0631\\u0648\\u0632 \\u0628\\u0627\\u0628\\u062a\\u0634\\u0627\\u0646 \\u0633\\u067e\\u0627\\u0633\\u06af\\u0632\\u0627\\u0631\\u06cc\\u060c \\u0628\\u0631\\u0627\\u06cc \\u062e\\u0648\\u062f\\u062a \\u0628\\u0646\\u0648\\u06cc\\u0633\",\"en\":\"Write down three things you\'re grateful for today\"}',NULL,NULL,'mindfulness',1,7,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(8,'screen-free-hour','{\"fa\":\"\\u06cc\\u06a9 \\u0633\\u0627\\u0639\\u062a \\u0628\\u062f\\u0648\\u0646 \\u0635\\u0641\\u062d\\u0647\\u200c\\u0646\\u0645\\u0627\\u06cc\\u0634\",\"en\":\"One screen-free hour\"}','{\"fa\":\"\\u06cc\\u06a9 \\u0633\\u0627\\u0639\\u062a \\u0627\\u0632 \\u0627\\u0645\\u0631\\u0648\\u0632 \\u0631\\u0627 \\u0628\\u062f\\u0648\\u0646 \\u06af\\u0648\\u0634\\u06cc \\u0648 \\u0646\\u0645\\u0627\\u06cc\\u0634\\u06af\\u0631 \\u0628\\u06af\\u0630\\u0631\\u0627\\u0646\",\"en\":\"Spend one hour today away from phones and screens\"}',NULL,NULL,'mindfulness',1,8,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(9,'healthy-meal','{\"fa\":\"\\u06cc\\u06a9 \\u0648\\u0639\\u062f\\u0647\\u200c\\u06cc \\u0633\\u0627\\u0644\\u0645 \\u0628\\u062e\\u0648\\u0631\",\"en\":\"Eat one healthy meal\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u06cc\\u06a9 \\u0648\\u0639\\u062f\\u0647\\u200c\\u06cc \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u0648 \\u0645\\u063a\\u0630\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u062e\\u0648\\u062f\\u062a \\u0622\\u0645\\u0627\\u062f\\u0647 \\u06a9\\u0646\",\"en\":\"Prepare one balanced, nutritious meal today\"}',NULL,NULL,'nutrition',1,9,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(10,'drink-water','{\"fa\":\"\\u0647\\u0634\\u062a \\u0644\\u06cc\\u0648\\u0627\\u0646 \\u0622\\u0628\",\"en\":\"Eight glasses of water\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u0647\\u0634\\u062a \\u0644\\u06cc\\u0648\\u0627\\u0646 \\u0622\\u0628 \\u0628\\u0646\\u0648\\u0634\\u061b \\u06a9\\u0645\\u200c\\u0622\\u0628\\u06cc \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0631\\u0627 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\",\"en\":\"Drink eight glasses of water today \\u2014 dehydration deepens fatigue\"}',NULL,NULL,'nutrition',1,10,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(11,'iron-rich-food','{\"fa\":\"\\u06cc\\u06a9 \\u062e\\u0648\\u0631\\u0627\\u06a9\\u06cc \\u0622\\u0647\\u0646\\u200c\\u062f\\u0627\\u0631\",\"en\":\"One iron-rich food\"}','{\"fa\":\"\\u062e\\u0648\\u0631\\u0627\\u06a9\\u06cc \\u0622\\u0647\\u0646\\u200c\\u062f\\u0627\\u0631 \\u0645\\u062b\\u0644 \\u0639\\u062f\\u0633\\u060c \\u0627\\u0633\\u0641\\u0646\\u0627\\u062c \\u06cc\\u0627 \\u062e\\u0631\\u0645\\u0627 \\u0628\\u0647 \\u0648\\u0639\\u062f\\u0647\\u200c\\u0627\\u062a \\u0627\\u0636\\u0627\\u0641\\u0647 \\u06a9\\u0646\",\"en\":\"Add an iron-rich food like lentils, spinach or dates to a meal\"}',NULL,NULL,'nutrition',1,11,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(12,'no-added-sugar','{\"fa\":\"\\u06cc\\u06a9 \\u0631\\u0648\\u0632 \\u0628\\u062f\\u0648\\u0646 \\u0642\\u0646\\u062f \\u0627\\u0641\\u0632\\u0648\\u062f\\u0647\",\"en\":\"A day without added sugar\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u0631\\u0627 \\u0628\\u062f\\u0648\\u0646 \\u0646\\u0648\\u0634\\u06cc\\u062f\\u0646\\u06cc \\u0648 \\u062e\\u0648\\u0631\\u0627\\u06a9\\u06cc \\u0634\\u06cc\\u0631\\u06cc\\u0646\\u200c\\u0634\\u062f\\u0647 \\u0628\\u06af\\u0630\\u0631\\u0627\\u0646\",\"en\":\"Go today without sweetened drinks or snacks\"}',NULL,NULL,'nutrition',1,12,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(13,'walk-20-minutes','{\"fa\":\"\\u06f2\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\",\"en\":\"Walk for 20 minutes\"}','{\"fa\":\"\\u06cc\\u06a9 \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0633\\u0628\\u06a9 \\u06f2\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647\\u200c\\u0627\\u06cc \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0628\\u062f\\u0647\",\"en\":\"Go for a light 20-minute walk\"}',NULL,NULL,'exercise',1,13,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(14,'gentle-stretch','{\"fa\":\"\\u06f5 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u06a9\\u0634\\u0634\",\"en\":\"5 minutes of stretching\"}','{\"fa\":\"\\u0686\\u0646\\u062f \\u062d\\u0631\\u06a9\\u062a \\u06a9\\u0634\\u0634\\u06cc \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0645\\u0631 \\u0648 \\u0644\\u06af\\u0646 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0628\\u062f\\u0647\",\"en\":\"Do a few gentle stretches for your lower back and hips\"}',1,5,'exercise',1,14,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(15,'strength-session','{\"fa\":\"\\u06cc\\u06a9 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u0642\\u062f\\u0631\\u062a\\u06cc \\u06a9\\u0648\\u062a\\u0627\\u0647\",\"en\":\"A short strength session\"}','{\"fa\":\"\\u0627\\u0646\\u0631\\u0698\\u06cc \\u0627\\u0645\\u0631\\u0648\\u0632\\u062a \\u062e\\u0648\\u0628 \\u0627\\u0633\\u062a\\u061b \\u06f2\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u0642\\u062f\\u0631\\u062a\\u06cc \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0628\\u062f\\u0647\",\"en\":\"Your energy is up today \\u2014 do 20 minutes of strength work\"}',NULL,NULL,'exercise',1,15,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(16,'sleep-earlier','{\"fa\":\"\\u0632\\u0648\\u062f\\u062a\\u0631 \\u0628\\u062e\\u0648\\u0627\\u0628\",\"en\":\"Go to bed earlier\"}','{\"fa\":\"\\u0627\\u0645\\u0634\\u0628 \\u06f3\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u0632\\u0648\\u062f\\u062a\\u0631 \\u0628\\u062e\\u0648\\u0627\\u0628 \\u062a\\u0627 \\u062e\\u0648\\u0627\\u0628 \\u0628\\u0647\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\",\"en\":\"Sleep 30 minutes earlier tonight for better rest\"}',NULL,NULL,'sleep',1,16,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(17,'no-caffeine-after-four','{\"fa\":\"\\u0628\\u0639\\u062f \\u0627\\u0632 \\u0639\\u0635\\u0631 \\u0628\\u062f\\u0648\\u0646 \\u06a9\\u0627\\u0641\\u0626\\u06cc\\u0646\",\"en\":\"No caffeine after 4pm\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u0628\\u0639\\u062f \\u0627\\u0632 \\u0633\\u0627\\u0639\\u062a \\u06f4 \\u0686\\u0627\\u06cc \\u0648 \\u0642\\u0647\\u0648\\u0647 \\u0646\\u062e\\u0648\\u0631 \\u062a\\u0627 \\u0634\\u0628 \\u0631\\u0627\\u062d\\u062a\\u200c\\u062a\\u0631 \\u0628\\u062e\\u0648\\u0627\\u0628\\u06cc\",\"en\":\"Skip coffee and tea after 4pm for an easier night\"}',NULL,NULL,'sleep',1,17,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(18,'phone-out-of-bedroom','{\"fa\":\"\\u06af\\u0648\\u0634\\u06cc \\u0628\\u06cc\\u0631\\u0648\\u0646 \\u0627\\u0632 \\u0627\\u062a\\u0627\\u0642 \\u062e\\u0648\\u0627\\u0628\",\"en\":\"Phone out of the bedroom\"}','{\"fa\":\"\\u0627\\u0645\\u0634\\u0628 \\u06af\\u0648\\u0634\\u06cc \\u0631\\u0627 \\u0628\\u06cc\\u0631\\u0648\\u0646 \\u0627\\u0632 \\u0627\\u062a\\u0627\\u0642 \\u0628\\u06af\\u0630\\u0627\\u0631 \\u0648 \\u0628\\u062f\\u0648\\u0646 \\u0622\\u0646 \\u0628\\u062e\\u0648\\u0627\\u0628\",\"en\":\"Leave your phone outside the bedroom tonight\"}',NULL,NULL,'sleep',1,18,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(19,'warm-compress-period','{\"fa\":\"\\u06a9\\u06cc\\u0633\\u0647\\u200c\\u06cc \\u0622\\u0628 \\u06af\\u0631\\u0645 \\u0631\\u0648\\u06cc \\u0634\\u06a9\\u0645\",\"en\":\"A warm compress on your belly\"}','{\"fa\":\"\\u0631\\u0648\\u0632\\u0647\\u0627\\u06cc \\u0627\\u0648\\u0644 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc\\u060c \\u06f1\\u06f5 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u06a9\\u06cc\\u0633\\u0647\\u200c\\u06cc \\u0622\\u0628 \\u06af\\u0631\\u0645 \\u062f\\u0631\\u062f\\u0650 \\u0634\\u06a9\\u0645 \\u0631\\u0627 \\u06a9\\u0645 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\",\"en\":\"In the first days of your period, 15 minutes of heat eases cramps\"}',1,3,'mindfulness',1,19,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(20,'rest-day-period','{\"fa\":\"\\u06cc\\u06a9 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0648\\u0627\\u0642\\u0639\\u06cc\",\"en\":\"A real rest\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u06cc\\u06a9 \\u06a9\\u0627\\u0631 \\u0627\\u0632 \\u0644\\u06cc\\u0633\\u062a\\u062a \\u0631\\u0627 \\u062d\\u0630\\u0641 \\u06a9\\u0646 \\u0648 \\u0628\\u0647 \\u0628\\u062f\\u0646\\u062a \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0628\\u062f\\u0647\",\"en\":\"Drop one thing from your list today and let your body rest\"}',1,4,'sleep',1,20,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(21,'iron-after-period','{\"fa\":\"\\u062c\\u0628\\u0631\\u0627\\u0646 \\u0622\\u0647\\u0646 \\u0628\\u0639\\u062f \\u0627\\u0632 \\u067e\\u0631\\u06cc\\u0648\\u062f\",\"en\":\"Replenish iron after your period\"}','{\"fa\":\"\\u0628\\u0639\\u062f \\u0627\\u0632 \\u062e\\u0648\\u0646\\u200c\\u0631\\u06cc\\u0632\\u06cc\\u060c \\u06cc\\u06a9 \\u0648\\u0639\\u062f\\u0647\\u200c\\u06cc \\u0622\\u0647\\u0646\\u200c\\u062f\\u0627\\u0631 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0648\\u06cc\\u062a\\u0627\\u0645\\u06cc\\u0646 C \\u0628\\u062e\\u0648\\u0631\",\"en\":\"After bleeding, pair an iron-rich meal with vitamin C\"}',5,9,'nutrition',1,21,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(22,'energy-peak-workout','{\"fa\":\"\\u0627\\u0632 \\u0627\\u0648\\u062c \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u06a9\\u0646\",\"en\":\"Use your energy peak\"}','{\"fa\":\"\\u0627\\u06cc\\u0646 \\u0631\\u0648\\u0632\\u0647\\u0627 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u067e\\u0631\\u0627\\u0646\\u0631\\u0698\\u06cc\\u200c\\u062a\\u0631\\u06cc\\u0646 \\u0631\\u0648\\u0632\\u0647\\u0627\\u06cc \\u0686\\u0631\\u062e\\u0647\\u200c\\u0627\\u0646\\u062f\\u061b \\u06cc\\u06a9 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u062c\\u062f\\u06cc\\u200c\\u062a\\u0631 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0628\\u062f\\u0647\",\"en\":\"These are usually your highest-energy days \\u2014 take on a harder workout\"}',8,14,'exercise',1,22,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(23,'log-fertility-signs','{\"fa\":\"\\u0646\\u0634\\u0627\\u0646\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u062b\\u0628\\u062a \\u06a9\\u0646\",\"en\":\"Log your ovulation signs\"}','{\"fa\":\"\\u062a\\u0631\\u0634\\u062d\\u0627\\u062a \\u0648 \\u062f\\u0645\\u0627\\u06cc \\u0628\\u062f\\u0646\\u062a \\u0631\\u0627 \\u0627\\u06cc\\u0646 \\u0631\\u0648\\u0632\\u0647\\u0627 \\u062b\\u0628\\u062a \\u06a9\\u0646 \\u062a\\u0627 \\u067e\\u0646\\u062c\\u0631\\u0647\\u200c\\u06cc \\u0628\\u0627\\u0631\\u0648\\u0631\\u06cc \\u062f\\u0642\\u06cc\\u0642\\u200c\\u062a\\u0631 \\u0634\\u0648\\u062f\",\"en\":\"Log discharge and temperature these days for a sharper fertile window\"}',12,17,'tracking',1,23,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(24,'magnesium-before-period','{\"fa\":\"\\u0645\\u0646\\u06cc\\u0632\\u06cc\\u0645 \\u0642\\u0628\\u0644 \\u0627\\u0632 \\u067e\\u0631\\u06cc\\u0648\\u062f\",\"en\":\"Magnesium before your period\"}','{\"fa\":\"\\u062e\\u0648\\u0631\\u0627\\u06a9\\u06cc\\u200c\\u0647\\u0627\\u06cc \\u067e\\u0631\\u0645\\u0646\\u06cc\\u0632\\u06cc\\u0645 \\u0645\\u062b\\u0644 \\u0628\\u0627\\u062f\\u0627\\u0645 \\u0648 \\u0634\\u06a9\\u0644\\u0627\\u062a \\u062a\\u0644\\u062e \\u0628\\u0647 \\u0633\\u0646\\u062f\\u0631\\u0645 \\u067e\\u06cc\\u0634 \\u0627\\u0632 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f\",\"en\":\"Magnesium-rich foods like almonds and dark chocolate help with PMS\"}',20,28,'nutrition',1,24,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(25,'gentle-with-yourself-pms','{\"fa\":\"\\u0628\\u0627 \\u062e\\u0648\\u062f\\u062a \\u0645\\u0647\\u0631\\u0628\\u0627\\u0646 \\u0628\\u0627\\u0634\",\"en\":\"Be gentle with yourself\"}','{\"fa\":\"\\u0631\\u0648\\u0632\\u0647\\u0627\\u06cc \\u067e\\u06cc\\u0634 \\u0627\\u0632 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc \\u0646\\u0648\\u0633\\u0627\\u0646 \\u062e\\u0644\\u0642 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061b \\u0627\\u0645\\u0631\\u0648\\u0632 \\u06cc\\u06a9 \\u06a9\\u0627\\u0631 \\u0622\\u0631\\u0627\\u0645\\u200c\\u0628\\u062e\\u0634 \\u0628\\u0631\\u0627\\u06cc \\u062e\\u0648\\u062f\\u062a \\u0628\\u06a9\\u0646\",\"en\":\"Mood swings before your period are normal \\u2014 do one calming thing for yourself today\"}',24,35,'mindfulness',1,25,'2026-09-23 09:00:00','2026-09-23 09:00:00');
