(1,'help','home','{\"fa\":\"\\u062e\\u0627\\u0646\\u0647\",\"en\":\"Home\"}','{\"fa\":\"\\u062a\\u0648\\u06cc \\u0635\\u0641\\u062d\\u0647 \\u062e\\u0627\\u0646\\u0647\\u060c \\u062e\\u0644\\u0627\\u0635\\u0647\\u200c\\u0627\\u06cc \\u0627\\u0632 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0627\\u0645\\u0631\\u0648\\u0632\\u062a \\u0631\\u0648 \\u0645\\u06cc\\u200c\\u0628\\u06cc\\u0646\\u06cc: \\u0631\\u0648\\u0632 \\u0686\\u0631\\u062e\\u0647 \\u06cc\\u0627 \\u0647\\u0641\\u062a\\u0647 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc\\u060c \\u067e\\u06cc\\u0634\\u200c\\u0628\\u06cc\\u0646\\u06cc\\u200c\\u0647\\u0627\\u06cc \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0648 \\u067e\\u06cc\\u0627\\u0645 \\u0631\\u0648\\u0632\\u0627\\u0646\\u0647\\u200c\\u0627\\u06cc \\u06a9\\u0647 \\u0645\\u062e\\u0635\\u0648\\u0635 \\u0634\\u0631\\u0627\\u06cc\\u0637 \\u062e\\u0648\\u062f\\u062a\\u0647.\",\"en\":\"The home screen shows a summary of your day: your cycle day or pregnancy week, upcoming predictions, and a daily message tailored to you.\"}',NULL,NULL,1,10,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(2,'help','calendar','{\"fa\":\"\\u062a\\u0642\\u0648\\u06cc\\u0645\",\"en\":\"Calendar\"}','{\"fa\":\"\\u062a\\u0642\\u0648\\u06cc\\u0645 \\u0634\\u0645\\u0633\\u06cc\\u060c \\u062f\\u0648\\u0631\\u0647\\u200c\\u0647\\u0627\\u06cc\\u06cc \\u06a9\\u0647 \\u062b\\u0628\\u062a \\u06a9\\u0631\\u062f\\u06cc \\u0648 \\u0631\\u0648\\u0632\\u0647\\u0627\\u06cc \\u067e\\u06cc\\u0634\\u200c\\u0628\\u06cc\\u0646\\u06cc\\u200c\\u0634\\u062f\\u0647 \\u0631\\u0648 \\u0646\\u0634\\u0648\\u0646 \\u0645\\u06cc\\u200c\\u062f\\u0647. \\u0628\\u0627 \\u0632\\u062f\\u0646 \\u0631\\u0648\\u06cc \\u0647\\u0631 \\u0631\\u0648\\u0632 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0646\\u06cc \\u062c\\u0632\\u0626\\u06cc\\u0627\\u062a \\u0647\\u0645\\u0648\\u0646 \\u0631\\u0648\\u0632 \\u0631\\u0648 \\u0628\\u0628\\u06cc\\u0646\\u06cc \\u06cc\\u0627 \\u0648\\u06cc\\u0631\\u0627\\u06cc\\u0634\\u0634 \\u06a9\\u0646\\u06cc.\",\"en\":\"The Jalali calendar displays your logged periods and predicted days. Tap any day to see its details or edit its information.\"}',NULL,NULL,1,20,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(3,'help','daily-log','{\"fa\":\"\\u062b\\u0628\\u062a \\u0631\\u0648\\u0632\\u0627\\u0646\\u0647\",\"en\":\"Daily log\"}','{\"fa\":\"\\u0627\\u0632 \\u0628\\u062e\\u0634 \\u062b\\u0628\\u062a \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0646\\u06cc \\u0647\\u0631 \\u0631\\u0648\\u0632 \\u062d\\u0627\\u0644 \\u0639\\u0645\\u0648\\u0645\\u06cc\\u060c \\u0639\\u0644\\u0627\\u0626\\u0645\\u060c \\u0645\\u06cc\\u0632\\u0627\\u0646 \\u062e\\u0648\\u0646\\u0631\\u06cc\\u0632\\u06cc \\u0648 \\u0628\\u0642\\u06cc\\u0647 \\u0686\\u06cc\\u0632\\u0647\\u0627 \\u0631\\u0648 \\u062b\\u0628\\u062a \\u06a9\\u0646\\u06cc. \\u0647\\u0631\\u0686\\u06cc \\u0645\\u0646\\u0638\\u0645\\u200c\\u062a\\u0631 \\u062b\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u060c \\u067e\\u06cc\\u0634\\u200c\\u0628\\u06cc\\u0646\\u06cc\\u200c\\u0647\\u0627 \\u062f\\u0642\\u06cc\\u0642\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0646.\",\"en\":\"From the log section you can record your general mood, symptoms, flow, and more each day. Logging regularly improves the accuracy of predictions.\"}',NULL,NULL,1,30,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(4,'help','profile','{\"fa\":\"\\u067e\\u0631\\u0648\\u0641\\u0627\\u06cc\\u0644\",\"en\":\"Profile\"}','{\"fa\":\"\\u062a\\u0648\\u06cc \\u067e\\u0631\\u0648\\u0641\\u0627\\u06cc\\u0644 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0646\\u06cc \\u0627\\u0637\\u0644\\u0627\\u0639\\u0627\\u062a \\u0634\\u062e\\u0635\\u06cc \\u0648 \\u0633\\u0644\\u0627\\u0645\\u062a\\u06cc\\u062a \\u0631\\u0648 \\u0648\\u06cc\\u0631\\u0627\\u06cc\\u0634 \\u06a9\\u0646\\u06cc\\u060c \\u0632\\u0628\\u0627\\u0646 \\u0627\\u067e \\u0631\\u0648 \\u0639\\u0648\\u0636 \\u06a9\\u0646\\u06cc\\u060c \\u06cc\\u0647 \\u0646\\u0633\\u062e\\u0647 \\u0627\\u0632 \\u062f\\u0627\\u062f\\u0647\\u200c\\u0647\\u0627\\u062a \\u0631\\u0648 \\u0628\\u06af\\u06cc\\u0631\\u06cc \\u06cc\\u0627 \\u062d\\u0633\\u0627\\u0628\\u062a \\u0631\\u0648 \\u062d\\u0630\\u0641 \\u06a9\\u0646\\u06cc.\",\"en\":\"In your profile you can edit your personal and health information, change the app language, download a copy of your data, or delete your account.\"}',NULL,NULL,1,40,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(5,'help','support','{\"fa\":\"\\u067e\\u0634\\u062a\\u06cc\\u0628\\u0627\\u0646\\u06cc\",\"en\":\"Support\"}','{\"fa\":\"\\u0627\\u06af\\u0647 \\u0633\\u0624\\u0627\\u0644\\u06cc \\u062f\\u0627\\u0631\\u06cc \\u06cc\\u0627 \\u0628\\u0647 \\u0645\\u0634\\u06a9\\u0644\\u06cc \\u062e\\u0648\\u0631\\u062f\\u06cc\\u060c \\u0628\\u0631\\u0627\\u0645\\u0648\\u0646 \\u0628\\u0646\\u0648\\u06cc\\u0633\\u061b \\u0647\\u0631 \\u0686\\u0647 \\u0632\\u0648\\u062f\\u062a\\u0631 \\u062c\\u0648\\u0627\\u0628\\u062a \\u0631\\u0648 \\u0645\\u06cc\\u200c\\u062f\\u06cc\\u0645.\",\"en\":\"If you have a question or run into a problem, write to us and we\'ll get back to you as soon as we can.\"}','{\"fa\":\"\\u0627\\u0631\\u0633\\u0627\\u0644 \\u0627\\u06cc\\u0645\\u06cc\\u0644 \\u0628\\u0647 \\u067e\\u0634\\u062a\\u06cc\\u0628\\u0627\\u0646\\u06cc\",\"en\":\"Email support\"}','mailto:support@ritmesalamat.com',1,50,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(6,'privacy','commitment','{\"fa\":\"\\u0642\\u0648\\u0644\\u06cc \\u06a9\\u0647 \\u0628\\u0647\\u062a \\u0645\\u06cc\\u200c\\u062f\\u06cc\\u0645\",\"en\":\"Our commitment to you\"}','{\"fa\":\"\\u0631\\u06cc\\u062a\\u0645\\u06cc \\u062c\\u0627\\u06cc\\u06cc\\u0647 \\u06a9\\u0647 \\u062e\\u0635\\u0648\\u0635\\u06cc\\u200c\\u062a\\u0631\\u06cc\\u0646 \\u0627\\u0637\\u0644\\u0627\\u0639\\u0627\\u062a \\u0633\\u0644\\u0627\\u0645\\u062a\\u06cc\\u200c\\u0627\\u062a \\u0631\\u0648 \\u062b\\u0628\\u062a \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u06cc\\u061b \\u0628\\u0631\\u0627\\u06cc \\u0647\\u0645\\u06cc\\u0646 \\u062d\\u0631\\u06cc\\u0645 \\u062e\\u0635\\u0648\\u0635\\u06cc \\u067e\\u06cc\\u0634\\u200c\\u0641\\u0631\\u0636 \\u0645\\u0627\\u0633\\u062a\\u060c \\u0646\\u0647 \\u06cc\\u0647 \\u06af\\u0632\\u06cc\\u0646\\u0647. \\u0645\\u0627 \\u0641\\u0642\\u0637 \\u0647\\u0645\\u0648\\u0646 \\u062d\\u062f\\u0627\\u0642\\u0644 \\u0627\\u0637\\u0644\\u0627\\u0639\\u0627\\u062a\\u06cc \\u0631\\u0648 \\u062c\\u0645\\u0639 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u06cc\\u0645 \\u06a9\\u0647 \\u0627\\u067e \\u0628\\u062f\\u0648\\u0646 \\u0627\\u0648\\u0646 \\u06a9\\u0627\\u0631 \\u0646\\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0647 \\u0648 \\u0647\\u06cc\\u0686 \\u062f\\u0627\\u062f\\u0647\\u200c\\u0627\\u06cc \\u0631\\u0648 \\u00ab\\u0628\\u0631\\u0627\\u06cc \\u0631\\u0648\\u0632 \\u0645\\u0628\\u0627\\u062f\\u0627\\u00bb \\u0646\\u06af\\u0647 \\u0646\\u0645\\u06cc\\u200c\\u062f\\u0627\\u0631\\u06cc\\u0645.\",\"en\":\"Ritme is built to hold some of your most personal health information, so privacy is our default, not an option. We collect only the minimum data the app needs to work, and we never store anything \\\"just in case\\\".\"}',NULL,NULL,1,10,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(7,'privacy','never-sold','{\"fa\":\"\\u062f\\u0627\\u062f\\u0647\\u200c\\u0647\\u0627\\u062a \\u0641\\u0631\\u0648\\u062e\\u062a\\u0647 \\u0646\\u0645\\u06cc\\u200c\\u0634\\u0647\",\"en\":\"Your data is never sold\"}','{\"fa\":\"\\u0627\\u0637\\u0644\\u0627\\u0639\\u0627\\u062a\\u062a \\u0647\\u06cc\\u0686\\u200c\\u0648\\u0642\\u062a \\u0628\\u0647 \\u0647\\u06cc\\u0686 \\u0634\\u062e\\u0635 \\u06cc\\u0627 \\u0634\\u0631\\u06a9\\u062a\\u06cc \\u0641\\u0631\\u0648\\u062e\\u062a\\u0647 \\u06cc\\u0627 \\u0627\\u062c\\u0627\\u0631\\u0647 \\u062f\\u0627\\u062f\\u0647 \\u0646\\u0645\\u06cc\\u200c\\u0634\\u0647 \\u0648 \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0628\\u0644\\u06cc\\u063a\\u0627\\u062a \\u0647\\u0645 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u0646\\u0645\\u06cc\\u200c\\u0634\\u0647. \\u062f\\u0627\\u062f\\u0647\\u200c\\u0647\\u0627\\u062a \\u0641\\u0642\\u0637 \\u0628\\u0631\\u0627\\u06cc \\u0627\\u06cc\\u0646\\u200c\\u06a9\\u0647 \\u0631\\u06cc\\u062a\\u0645\\u06cc \\u0628\\u0647 \\u062e\\u0648\\u062f\\u062a \\u0633\\u0631\\u0648\\u06cc\\u0633 \\u0628\\u062f\\u0647 \\u0628\\u0647 \\u06a9\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u0631\\u0647.\",\"en\":\"Your information is never sold or rented to any person or company, and it is not used for advertising. Your data is used solely to provide Ritme\'s services to you.\"}',NULL,NULL,1,20,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(8,'privacy','health-confidential','{\"fa\":\"\\u062f\\u0627\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0644\\u0627\\u0645\\u062a\\u06cc\\u200c\\u0627\\u062a \\u0645\\u062d\\u0631\\u0645\\u0627\\u0646\\u0647 \\u0645\\u06cc\\u200c\\u0645\\u0648\\u0646\\u0647\",\"en\":\"Health data stays confidential\"}','{\"fa\":\"\\u062a\\u0627\\u0631\\u06cc\\u062e\\u200c\\u0647\\u0627\\u06cc \\u062f\\u0648\\u0631\\u0647\\u060c \\u0639\\u0644\\u0627\\u0626\\u0645\\u060c \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0648 \\u067e\\u06cc\\u0634\\u200c\\u0628\\u06cc\\u0646\\u06cc\\u200c\\u0647\\u0627 \\u0647\\u06cc\\u0686\\u200c\\u0648\\u0642\\u062a \\u062a\\u0648\\u06cc \\u06af\\u0632\\u0627\\u0631\\u0634\\u200c\\u0647\\u0627\\u06cc \\u0641\\u0646\\u06cc\\u060c \\u0627\\u0628\\u0632\\u0627\\u0631\\u0647\\u0627\\u06cc \\u062a\\u062d\\u0644\\u06cc\\u0644\\u06cc \\u06cc\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062e\\u0637\\u0627 \\u062b\\u0628\\u062a \\u0646\\u0645\\u06cc\\u200c\\u0634\\u0646 \\u0648 \\u0628\\u0627 \\u0647\\u06cc\\u0686 \\u0633\\u0631\\u0648\\u06cc\\u0633 \\u0634\\u062e\\u0635 \\u062b\\u0627\\u0644\\u062b\\u06cc \\u0628\\u0647 \\u0627\\u0634\\u062a\\u0631\\u0627\\u06a9 \\u06af\\u0630\\u0627\\u0634\\u062a\\u0647 \\u0646\\u0645\\u06cc\\u200c\\u0634\\u0646. \\u0641\\u0642\\u0637 \\u0628\\u0627 \\u0648\\u0631\\u0648\\u062f \\u0627\\u0645\\u0646 \\u062e\\u0648\\u062f\\u062a \\u0628\\u0647 \\u062d\\u0633\\u0627\\u0628 \\u06a9\\u0627\\u0631\\u0628\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u0634\\u0647 \\u0628\\u0647 \\u0627\\u06cc\\u0646 \\u062f\\u0627\\u062f\\u0647\\u200c\\u0647\\u0627 \\u0631\\u0633\\u06cc\\u062f.\",\"en\":\"Period dates, symptoms, pregnancy status, and predictions are never written to technical logs, analytics tools, or error reports, and they are never shared with third-party services. This data is only accessible through your own secure sign-in.\"}',NULL,NULL,1,30,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(9,'privacy','export-delete','{\"fa\":\"\\u0647\\u0631 \\u0648\\u0642\\u062a \\u062e\\u0648\\u0627\\u0633\\u062a\\u06cc\\u060c \\u062f\\u0627\\u062f\\u0647\\u200c\\u0647\\u0627\\u062a \\u0631\\u0648 \\u0628\\u06af\\u06cc\\u0631 \\u06cc\\u0627 \\u067e\\u0627\\u06a9 \\u06a9\\u0646\",\"en\":\"Your right to export and delete\"}','{\"fa\":\"\\u062f\\u0627\\u062f\\u0647\\u200c\\u0647\\u0627 \\u0645\\u0627\\u0644 \\u062e\\u0648\\u062f\\u062a\\u0647. \\u0647\\u0631 \\u0648\\u0642\\u062a \\u0628\\u062e\\u0648\\u0627\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0646\\u06cc \\u0627\\u0632 \\u0628\\u062e\\u0634 \\u067e\\u0631\\u0648\\u0641\\u0627\\u06cc\\u0644\\u060c \\u06cc\\u0647 \\u0646\\u0633\\u062e\\u0647 \\u06a9\\u0627\\u0645\\u0644 \\u0627\\u0632 \\u0627\\u0637\\u0644\\u0627\\u0639\\u0627\\u062a\\u062a \\u0631\\u0648 \\u062a\\u0648\\u06cc \\u06cc\\u0647 \\u0641\\u0627\\u06cc\\u0644 \\u0628\\u06af\\u06cc\\u0631\\u06cc \\u06cc\\u0627 \\u062d\\u0633\\u0627\\u0628\\u062a \\u0648 \\u0647\\u0645\\u0647 \\u062f\\u0627\\u062f\\u0647\\u200c\\u0647\\u0627\\u0634 \\u0631\\u0648 \\u0628\\u0631\\u0627\\u06cc \\u0647\\u0645\\u06cc\\u0634\\u0647 \\u062d\\u0630\\u0641 \\u06a9\\u0646\\u06cc. \\u062d\\u0630\\u0641 \\u062d\\u0633\\u0627\\u0628 \\u0641\\u0648\\u0631\\u06cc\\u0647 \\u0648 \\u0628\\u0631\\u06af\\u0634\\u062a\\u06cc \\u0646\\u062f\\u0627\\u0631\\u0647.\",\"en\":\"You own your data. At any time, you can download a complete copy of your information as a file from your profile, or permanently delete your account and everything in it. Account deletion is immediate and irreversible.\"}',NULL,NULL,1,40,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(10,'terms','informational-not-medical-advice','{\"fa\":\"\\u0627\\u0637\\u0644\\u0627\\u0639\\u200c\\u0631\\u0633\\u0627\\u0646\\u06cc\\u0647\\u060c \\u0646\\u0647 \\u062a\\u0648\\u0635\\u06cc\\u0647 \\u067e\\u0632\\u0634\\u06a9\\u06cc\",\"en\":\"Informational, not medical advice\"}','{\"fa\":\"\\u0645\\u062d\\u062a\\u0648\\u0627 \\u0648 \\u067e\\u06cc\\u0634\\u200c\\u0628\\u06cc\\u0646\\u06cc\\u200c\\u0647\\u0627\\u06cc \\u0631\\u06cc\\u062a\\u0645\\u06cc \\u2014 \\u0627\\u0632 \\u062c\\u0645\\u0644\\u0647 \\u067e\\u06cc\\u0634\\u200c\\u0628\\u06cc\\u0646\\u06cc \\u0632\\u0645\\u0627\\u0646 \\u062f\\u0648\\u0631\\u0647\\u060c \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc \\u0648 \\u0645\\u062d\\u062a\\u0648\\u0627\\u06cc \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u2014 \\u0641\\u0642\\u0637 \\u062c\\u0646\\u0628\\u0647 \\u0627\\u0637\\u0644\\u0627\\u0639\\u200c\\u0631\\u0633\\u0627\\u0646\\u06cc \\u062f\\u0627\\u0631\\u0647 \\u0648 \\u062c\\u0627\\u06cc \\u0645\\u0639\\u0627\\u06cc\\u0646\\u0647\\u060c \\u062a\\u0634\\u062e\\u06cc\\u0635 \\u06cc\\u0627 \\u062a\\u0648\\u0635\\u06cc\\u0647 \\u067e\\u0632\\u0634\\u06a9 \\u0631\\u0648 \\u0646\\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u0647. \\u0628\\u0631\\u0627\\u06cc \\u0647\\u0631 \\u062a\\u0635\\u0645\\u06cc\\u0645\\u06cc \\u06a9\\u0647 \\u0628\\u0647 \\u0633\\u0644\\u0627\\u0645\\u062a\\u06cc\\u062a \\u0645\\u0631\\u0628\\u0648\\u0637\\u0647\\u060c \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u06cc\\u0627 \\u0645\\u0627\\u0645\\u0627 \\u0645\\u0634\\u0648\\u0631\\u062a \\u06a9\\u0646.\",\"en\":\"Ritme\'s content and predictions \\u2014 including period and ovulation predictions and weekly pregnancy content \\u2014 are for informational purposes only and are not a substitute for examination, diagnosis, or advice from a doctor. For any health-related decision, please consult a physician or midwife.\"}',NULL,NULL,1,10,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(11,'terms','acceptable-use','{\"fa\":\"\\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u062f\\u0631\\u0633\\u062a \\u0627\\u0632 \\u0627\\u067e\",\"en\":\"Acceptable use\"}','{\"fa\":\"\\u0631\\u06cc\\u062a\\u0645\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u0634\\u062e\\u0635\\u06cc \\u062e\\u0648\\u062f\\u062a\\u0647. \\u0627\\u0637\\u0644\\u0627\\u0639\\u0627\\u062a \\u0631\\u0648 \\u0635\\u0627\\u062f\\u0642\\u0627\\u0646\\u0647 \\u0648 \\u0628\\u0631\\u0627\\u06cc \\u062d\\u0633\\u0627\\u0628 \\u062e\\u0648\\u062f\\u062a \\u062b\\u0628\\u062a \\u06a9\\u0646\\u060c \\u0627\\u0632 \\u062d\\u0633\\u0627\\u0628 \\u062f\\u06cc\\u06af\\u0631\\u0627\\u0646 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u0646\\u06a9\\u0646 \\u0648 \\u0633\\u0631\\u0627\\u063a \\u062f\\u0633\\u062a\\u0631\\u0633\\u06cc \\u063a\\u06cc\\u0631\\u0645\\u062c\\u0627\\u0632 \\u0628\\u0647 \\u0633\\u0627\\u0645\\u0627\\u0646\\u0647 \\u06cc\\u0627 \\u062f\\u0627\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0628\\u0642\\u06cc\\u0647 \\u06a9\\u0627\\u0631\\u0628\\u0631\\u0647\\u0627 \\u0646\\u0631\\u0648.\",\"en\":\"Ritme is for your personal use. Please log information honestly and only for your own account, do not use someone else\'s account, and do not attempt unauthorized access to the system or to other users\' data.\"}',NULL,NULL,1,20,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(12,'terms','your-account-and-one-time-codes','{\"fa\":\"\\u062d\\u0633\\u0627\\u0628 \\u06a9\\u0627\\u0631\\u0628\\u0631\\u06cc \\u0648 \\u0648\\u0631\\u0648\\u062f \\u0628\\u0627 \\u06a9\\u062f \\u06cc\\u06a9\\u200c\\u0628\\u0627\\u0631\\u0645\\u0635\\u0631\\u0641\",\"en\":\"Your account and one-time codes\"}','{\"fa\":\"\\u0648\\u0631\\u0648\\u062f \\u0628\\u0647 \\u0631\\u06cc\\u062a\\u0645\\u06cc \\u0628\\u0627 \\u0634\\u0645\\u0627\\u0631\\u0647 \\u0645\\u0648\\u0628\\u0627\\u06cc\\u0644 \\u0648 \\u06a9\\u062f \\u06cc\\u06a9\\u200c\\u0628\\u0627\\u0631\\u0645\\u0635\\u0631\\u0641 (OTP) \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0647. \\u0627\\u0645\\u0646\\u06cc\\u062a \\u0634\\u0645\\u0627\\u0631\\u0647 \\u0645\\u0648\\u0628\\u0627\\u06cc\\u0644 \\u0648 \\u06af\\u0648\\u0634\\u06cc\\u062a \\u0628\\u0627 \\u062e\\u0648\\u062f\\u062a\\u0647\\u061b \\u06a9\\u062f \\u0648\\u0631\\u0648\\u062f \\u0631\\u0648 \\u062f\\u0631 \\u0627\\u062e\\u062a\\u06cc\\u0627\\u0631 \\u06a9\\u0633\\u06cc \\u0646\\u0630\\u0627\\u0631.\",\"en\":\"Signing in to Ritme uses your mobile number and a one-time code (OTP). Keeping your mobile number and device secure is your responsibility; never share your sign-in code with anyone.\"}',NULL,NULL,1,30,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(13,'terms','deleting-your-data','{\"fa\":\"\\u062d\\u0630\\u0641 \\u0627\\u0637\\u0644\\u0627\\u0639\\u0627\\u062a\",\"en\":\"Deleting your data\"}','{\"fa\":\"\\u0647\\u0631 \\u0648\\u0642\\u062a \\u0628\\u062e\\u0648\\u0627\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0646\\u06cc \\u062d\\u0633\\u0627\\u0628\\u062a \\u0631\\u0648 \\u0627\\u0632 \\u0628\\u062e\\u0634 \\u067e\\u0631\\u0648\\u0641\\u0627\\u06cc\\u0644 \\u062d\\u0630\\u0641 \\u06a9\\u0646\\u06cc. \\u0628\\u0627 \\u062d\\u0630\\u0641 \\u062d\\u0633\\u0627\\u0628\\u060c \\u0647\\u0645\\u0647 \\u062f\\u0627\\u062f\\u0647\\u200c\\u0647\\u0627\\u062a \\u0627\\u0632 \\u0633\\u0631\\u0648\\u0631\\u0647\\u0627\\u06cc \\u0645\\u0627 \\u067e\\u0627\\u06a9 \\u0645\\u06cc\\u200c\\u0634\\u0647 \\u0648 \\u0646\\u0634\\u0633\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0641\\u0639\\u0627\\u0644\\u062a \\u0647\\u0645 \\u0628\\u0627\\u0637\\u0644 \\u0645\\u06cc\\u200c\\u0634\\u0647.\",\"en\":\"You can delete your account from the profile section at any time. When you delete your account, all of your data is erased from our servers and your active sessions are revoked.\"}',NULL,NULL,1,40,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(14,'about','what-is-ritme','{\"fa\":\"\\u0631\\u06cc\\u062a\\u0645\\u06cc \\u0686\\u06cc\\u0647\\u061f\",\"en\":\"What is Ritme?\"}','{\"fa\":\"\\u0631\\u06cc\\u062a\\u0645\\u06cc \\u06cc\\u0647 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u062e\\u0635\\u0648\\u0635\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0633\\u0644\\u0627\\u0645\\u062a \\u0632\\u0646\\u0627\\u0646\\u0647\\u061b \\u0627\\u067e\\u06cc \\u06a9\\u0647 \\u06a9\\u0645\\u06a9\\u062a \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0647 \\u0631\\u06cc\\u062a\\u0645 \\u0628\\u062f\\u0646\\u062a \\u0631\\u0648 \\u0628\\u0647\\u062a\\u0631 \\u0628\\u0634\\u0646\\u0627\\u0633\\u06cc\\u060c \\u0647\\u0631 \\u0631\\u0648\\u0632 \\u062d\\u0627\\u0644 \\u0648 \\u0639\\u0644\\u0627\\u0626\\u0645\\u062a \\u0631\\u0648 \\u062b\\u0628\\u062a \\u06a9\\u0646\\u06cc \\u0648 \\u067e\\u06cc\\u0634\\u200c\\u0628\\u06cc\\u0646\\u06cc\\u200c\\u0647\\u0627 \\u0648 \\u0645\\u062d\\u062a\\u0648\\u0627\\u06cc\\u06cc \\u0645\\u062a\\u0646\\u0627\\u0633\\u0628 \\u0628\\u0627 \\u0634\\u0631\\u0627\\u06cc\\u0637 \\u062e\\u0648\\u062f\\u062a \\u0628\\u06af\\u06cc\\u0631\\u06cc.\",\"en\":\"Ritme is a private companion for women\'s health \\u2014 an app for understanding your body\'s rhythm, logging how you feel each day, and receiving predictions and content tailored to your situation.\"}',NULL,NULL,1,10,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(15,'about','two-modes-cycle-and-pregnancy','{\"fa\":\"\\u062f\\u0648 \\u062a\\u0627 \\u062d\\u0627\\u0644\\u062a: \\u0686\\u0631\\u062e\\u0647 \\u0648 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc\",\"en\":\"Two modes: cycle and pregnancy\"}','{\"fa\":\"\\u062a\\u0648\\u06cc \\u062d\\u0627\\u0644\\u062a \\u0686\\u0631\\u062e\\u0647\\u060c \\u0631\\u06cc\\u062a\\u0645\\u06cc \\u062f\\u0648\\u0631\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc\\u200c\\u0627\\u062a \\u0631\\u0648 \\u062b\\u0628\\u062a \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0647 \\u0648 \\u0632\\u0645\\u0627\\u0646 \\u062a\\u0642\\u0631\\u06cc\\u0628\\u06cc \\u062f\\u0648\\u0631\\u0647 \\u0628\\u0639\\u062f\\u06cc \\u0648 \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc \\u0631\\u0648 \\u067e\\u06cc\\u0634\\u200c\\u0628\\u06cc\\u0646\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0647. \\u062a\\u0648\\u06cc \\u062d\\u0627\\u0644\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc\\u060c \\u0647\\u0641\\u062a\\u0647\\u200c\\u0628\\u0647\\u200c\\u0647\\u0641\\u062a\\u0647 \\u06a9\\u0646\\u0627\\u0631\\u062a\\u0647: \\u0645\\u062d\\u062a\\u0648\\u0627\\u06cc \\u0645\\u062e\\u0635\\u0648\\u0635 \\u0647\\u0631 \\u0647\\u0641\\u062a\\u0647\\u060c \\u06cc\\u0627\\u062f\\u0622\\u0648\\u0631\\u0647\\u0627 \\u0648 \\u062b\\u0628\\u062a \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0648 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646. \\u0627\\u06cc\\u0646 \\u067e\\u06cc\\u0634\\u200c\\u0628\\u06cc\\u0646\\u06cc\\u200c\\u0647\\u0627 \\u0648 \\u0645\\u062d\\u062a\\u0648\\u0627\\u0647\\u0627 \\u0641\\u0642\\u0637 \\u0627\\u0637\\u0644\\u0627\\u0639\\u200c\\u0631\\u0633\\u0627\\u0646\\u06cc\\u0647 \\u0648 \\u062c\\u0627\\u06cc \\u0646\\u0638\\u0631 \\u067e\\u0632\\u0634\\u06a9 \\u0631\\u0648 \\u0646\\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u0647.\",\"en\":\"In cycle mode, Ritme tracks your menstrual cycles and estimates when your next period and ovulation are likely to occur. In pregnancy mode, it accompanies you week by week with stage-appropriate content, reminders, and tools to log symptoms and fetal movement. These predictions and content are informational and do not replace a doctor\'s advice.\"}',NULL,NULL,1,20,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(16,'about','app-version','{\"fa\":\"\\u0646\\u0633\\u062e\\u0647 \\u0627\\u067e\",\"en\":\"App version\"}','{\"fa\":\"\\u0627\\u0644\\u0627\\u0646 \\u062f\\u0627\\u0631\\u06cc \\u0627\\u0632 \\u0646\\u0633\\u062e\\u0647 \\u06f1\\u066b\\u06f0\\u066b\\u06f0 \\u0631\\u06cc\\u062a\\u0645\\u06cc \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u06cc. \\u0645\\u0627 \\u0645\\u0631\\u062a\\u0628 \\u0627\\u067e \\u0631\\u0648 \\u0628\\u0647\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u06cc\\u0645\\u061b \\u0646\\u0638\\u0631\\u062a \\u062a\\u0648\\u06cc \\u0627\\u06cc\\u0646 \\u0645\\u0633\\u06cc\\u0631 \\u062e\\u06cc\\u0644\\u06cc \\u0628\\u0631\\u0627\\u0645\\u0648\\u0646 \\u0627\\u0631\\u0632\\u0634 \\u062f\\u0627\\u0631\\u0647.\",\"en\":\"You are using Ritme version 1.0.0. We improve the app regularly \\u2014 your feedback is invaluable along the way.\"}',NULL,NULL,1,30,'2026-09-23 09:00:00','2026-09-23 09:00:00');
