INSERT INTO `message_contents` VALUES
(1,'cycle_base_non_ttc','menstruation','fa','cycle_base_non_ttc / menstruation','{\"short\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u0631\\u0648\\u0632 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0648 \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u062e\\u0648\\u062f\\u062a\\u0647\",\"long\":\"\\u062f\\u0631 \\u062f\\u0648\\u0631\\u0627\\u0646 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc\\u060c \\u0628\\u062f\\u0646\\u062a \\u0646\\u06cc\\u0627\\u0632 \\u0628\\u0647 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0648 \\u062a\\u0648\\u062c\\u0647 \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0631\\u0647. \\u0628\\u0647 \\u062e\\u0648\\u062f\\u062a \\u0627\\u062c\\u0627\\u0632\\u0647 \\u0628\\u062f\\u0647 \\u06a9\\u0645\\u06cc \\u0622\\u0631\\u0648\\u0645\\u200c\\u062a\\u0631 \\u0628\\u0627\\u0634\\u06cc \\u0648 \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0627\\u062c\\u062a\\u0646\\u0627\\u0628 \\u06a9\\u0646\\u06cc.\",\"action\":\"\\u06cc\\u06a9 \\u0646\\u0648\\u0634\\u06cc\\u062f\\u0646\\u06cc \\u06af\\u0631\\u0645 \\u0628\\u0646\\u0648\\u0634 \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0646\",\"dos\":[\"\\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc\",\"\\u0646\\u0648\\u0634\\u06cc\\u062f\\u0646 \\u0622\\u0628 \\u0641\\u0631\\u0627\\u0648\\u0627\\u0646\",\"\\u0645\\u0635\\u0631\\u0641 \\u0622\\u0647\\u0646\",\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0633\\u0628\\u06a9\"],\"donts\":[\"\\u0648\\u0631\\u0632\\u0634 \\u0633\\u0646\\u06af\\u06cc\\u0646\",\"\\u06a9\\u0627\\u0641\\u0626\\u06cc\\u0646 \\u0632\\u06cc\\u0627\\u062f\",\"\\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0634\\u0648\\u0631\",\"\\u0628\\u06cc\\u200c\\u062e\\u0648\\u0627\\u0628\\u06cc\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(2,'cycle_base_non_ttc','menstruation','en','cycle_base_non_ttc / menstruation','{\"short\":\"Today is a day for rest and self-care\",\"long\":\"During menstruation, your body needs more rest and attention. Allow yourself to slow down and avoid heavy activities.\",\"action\":\"Have a warm drink and rest\",\"dos\":[\"Get enough rest\",\"Drink plenty of water\",\"Take iron\",\"Light walking\"],\"donts\":[\"Heavy exercise\",\"Too much caffeine\",\"Salty foods\",\"Sleep deprivation\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
