(6,'cycle_base_non_ttc','ovulation','en','cycle_base_non_ttc / ovulation','{\"short\":\"You\'re at peak energy and attractiveness!\",\"long\":\"During ovulation, your energy, confidence and attractiveness are at their peak. Best time for presentations, negotiations and social activities.\",\"action\":\"Use this energy for important tasks\",\"dos\":[\"Strength training\",\"Presentations and negotiations\",\"Social activities\",\"Important decisions\"],\"donts\":[\"Wasting this energy\",\"Isolation\",\"Procrastination\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(7,'cycle_base_non_ttc','luteal','fa','cycle_base_non_ttc / luteal','{\"short\":\"\\u0648\\u0642\\u062a \\u062a\\u0645\\u0631\\u06a9\\u0632 \\u0631\\u0648\\u06cc \\u062e\\u0648\\u062f\\u062a \\u0648 \\u06a9\\u0627\\u0631\\u0647\\u0627\\u06cc \\u0646\\u06cc\\u0645\\u0647\\u200c\\u062a\\u0645\\u0627\\u0645\",\"long\":\"\\u062f\\u0631 \\u0641\\u0627\\u0632 \\u0644\\u0648\\u062a\\u0626\\u0627\\u0644\\u060c \\u0627\\u0646\\u0631\\u0698\\u06cc \\u06a9\\u0645\\u200c\\u06a9\\u0645 \\u06a9\\u0627\\u0647\\u0634 \\u067e\\u06cc\\u062f\\u0627 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0647. \\u0628\\u0647\\u062a\\u0631\\u06cc\\u0646 \\u0632\\u0645\\u0627\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u062a\\u06a9\\u0645\\u06cc\\u0644 \\u067e\\u0631\\u0648\\u0698\\u0647\\u200c\\u0647\\u0627\\u060c \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u062e\\u0648\\u062f \\u0648 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0633\\u06cc\\u06a9\\u0644 \\u0628\\u0639\\u062f\\u06cc.\",\"action\":\"\\u06cc\\u06a9 \\u06a9\\u0627\\u0631 \\u0646\\u06cc\\u0645\\u0647\\u200c\\u062a\\u0645\\u0627\\u0645 \\u0631\\u0648 \\u062a\\u0645\\u0648\\u0645 \\u06a9\\u0646\",\"dos\":[\"\\u06cc\\u0648\\u06af\\u0627 \\u0648 \\u06a9\\u0634\\u0634\",\"\\u062a\\u06a9\\u0645\\u06cc\\u0644 \\u067e\\u0631\\u0648\\u0698\\u0647\\u200c\\u0647\\u0627\",\"\\u062e\\u0648\\u0627\\u0628 \\u06a9\\u0627\\u0641\\u06cc\",\"\\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0645\\u063a\\u0630\\u06cc\"],\"donts\":[\"\\u0634\\u0631\\u0648\\u0639 \\u067e\\u0631\\u0648\\u0698\\u0647 \\u0628\\u0632\\u0631\\u06af\",\"\\u06a9\\u0627\\u0641\\u0626\\u06cc\\u0646 \\u0632\\u06cc\\u0627\\u062f\",\"\\u0634\\u06a9\\u0631 \\u0632\\u06cc\\u0627\\u062f\",\"\\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0627\\u0633\\u062a\\u0631\\u0633\\u200c\\u0632\\u0627\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(8,'cycle_base_non_ttc','luteal','en','cycle_base_non_ttc / luteal','{\"short\":\"Time to focus on yourself and unfinished tasks\",\"long\":\"In the luteal phase, energy gradually decreases. Best time to complete projects, self-care and prepare for the next cycle.\",\"action\":\"Complete an unfinished task\",\"dos\":[\"Yoga and stretching\",\"Complete projects\",\"Adequate sleep\",\"Nutritious foods\"],\"donts\":[\"Starting big projects\",\"Too much caffeine\",\"Too much sugar\",\"Stressful activities\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(9,'cycle_base_non_ttc','default','fa','cycle_base_non_ttc / default','{\"short\":\"\\u0628\\u0647 \\u0633\\u0644\\u0627\\u0645\\u062a \\u062e\\u0648\\u062f \\u062a\\u0648\\u062c\\u0647 \\u06a9\\u0646\\u06cc\\u062f\",\"long\":\"\\u0647\\u0631 \\u0631\\u0648\\u0632 \\u0641\\u0631\\u0635\\u062a\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u062e\\u0648\\u062f\\u062a\\u0647.\",\"action\":\"\\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\",\"dos\":[\"\\u0622\\u0628 \\u0641\\u0631\\u0627\\u0648\\u0627\\u0646\",\"\\u062e\\u0648\\u0627\\u0628 \\u06a9\\u0627\\u0641\\u06cc\",\"\\u0648\\u0631\\u0632\\u0634 \\u0645\\u0646\\u0638\\u0645\"],\"donts\":[\"\\u0627\\u0633\\u062a\\u0631\\u0633 \\u0632\\u06cc\\u0627\\u062f\",\"\\u0628\\u06cc\\u200c\\u062e\\u0648\\u0627\\u0628\\u06cc\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(10,'cycle_base_non_ttc','default','en','cycle_base_non_ttc / default','{\"short\":\"Take care of your health\",\"long\":\"Every day is an opportunity to take care of yourself.\",\"action\":\"Drink enough water\",\"dos\":[\"Plenty of water\",\"Adequate sleep\",\"Regular exercise\"],\"donts\":[\"Too much stress\",\"Sleep deprivation\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
