(12,'cycle_base_ttc','menstruation','en','cycle_base_ttc / menstruation','{\"short\":\"New cycle, new opportunity\",\"long\":\"A new cycle means a fresh chance for pregnancy. Use this time to rest and prepare your body.\",\"action\":\"Continue prenatal vitamins\",\"dos\":[\"Take folic acid\",\"Get enough rest\",\"Drink plenty of water\"],\"donts\":[\"Alcohol\",\"Smoking\",\"Too much stress\"],\"ttc_tips\":[\"Good time to check overall health\",\"Consult with your doctor\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
