(33,'cycle_override','acne','fa','cycle_override / acne','{\"message\":\"\\u062c\\u0648\\u0634\\u200c\\u0647\\u0627\\u06cc \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u06cc \\u0645\\u0648\\u0642\\u062a\\u06cc \\u0647\\u0633\\u062a\\u0646.\",\"action\":\"\\u067e\\u0627\\u06a9\\u0633\\u0627\\u0632\\u06cc \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u067e\\u0648\\u0633\\u062a\",\"dos\":[\"\\u0634\\u0633\\u062a\\u0634\\u0648\\u06cc \\u0645\\u0644\\u0627\\u06cc\\u0645\",\"\\u0622\\u0628 \\u0641\\u0631\\u0627\\u0648\\u0627\\u0646\",\"\\u0645\\u06cc\\u0648\\u0647 \\u0648 \\u0633\\u0628\\u0632\\u06cc\"],\"donts\":[\"\\u062f\\u0633\\u062a \\u0632\\u062f\\u0646 \\u0628\\u0647 \\u0635\\u0648\\u0631\\u062a\",\"\\u0634\\u06cc\\u0631\\u06cc\\u0646\\u06cc \\u0632\\u06cc\\u0627\\u062f\",\"\\u0622\\u0631\\u0627\\u06cc\\u0634 \\u0633\\u0646\\u06af\\u06cc\\u0646\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
