(37,'pregnancy_trimester','2','fa','pregnancy_trimester / 2','{\"short\":\"\\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u062f\\u0648\\u0645: \\u062f\\u0648\\u0631\\u0627\\u0646 \\u0637\\u0644\\u0627\\u06cc\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc\",\"long\":\"\\u0627\\u0646\\u0631\\u0698\\u06cc \\u0628\\u0631\\u06af\\u0634\\u062a\\u0647 \\u0648 \\u062a\\u0647\\u0648\\u0639\\u200c\\u0647\\u0627 \\u06a9\\u0645\\u062a\\u0631 \\u0634\\u062f\\u0647. \\u0632\\u0645\\u0627\\u0646 \\u0645\\u0646\\u0627\\u0633\\u0628\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0648\\u0631\\u0632\\u0634 \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0648 \\u0644\\u0630\\u062a \\u0628\\u0631\\u062f\\u0646 \\u0627\\u0632 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u0633\\u062a.\",\"action\":\"\\u0634\\u0646\\u0627 \\u06cc\\u0627 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u0627\\u0645\\u062a\\u062d\\u0627\\u0646 \\u06a9\\u0646\\u06cc\\u062f\",\"dos\":[\"\\u0648\\u0631\\u0632\\u0634 \\u0645\\u0644\\u0627\\u06cc\\u0645\",\"\\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u06a9\\u0627\\u0641\\u06cc\",\"\\u0622\\u0647\\u0646 \\u0648 \\u06a9\\u0644\\u0633\\u06cc\\u0645\",\"\\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc\"],\"donts\":[\"\\u062f\\u0631\\u0627\\u0632 \\u06a9\\u0634\\u06cc\\u062f\\u0646 \\u0628\\u0647 \\u067e\\u0634\\u062a \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc\",\"\\u0648\\u0631\\u0632\\u0634 \\u0633\\u0646\\u06af\\u06cc\\u0646\",\"\\u0633\\u0648\\u0646\\u0627 \\u0648 \\u062c\\u06a9\\u0648\\u0632\\u06cc\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
