(149,'pattern','recurring_pms','fa','pattern / recurring_pms','{\"message\":\"\\u0627\\u0644\\u06af\\u0648\\u06cc \\u062a\\u06a9\\u0631\\u0627\\u0631\\u06cc PMS \\u062f\\u0631 \\u062f\\u0627\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0634\\u0645\\u0627 \\u0645\\u0634\\u0627\\u0647\\u062f\\u0647 \\u0634\\u062f\\u0647. \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u06cc\\u062f \\u0628\\u0627 \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0642\\u0628\\u0644\\u06cc \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0631\\u0627 \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"recommendation\":\"\\u06cc\\u06a9 \\u0647\\u0641\\u062a\\u0647 \\u0642\\u0628\\u0644 \\u0627\\u0632 \\u067e\\u0631\\u06cc\\u0648\\u062f\\u060c \\u0645\\u0635\\u0631\\u0641 \\u0646\\u0645\\u06a9 \\u0648 \\u06a9\\u0627\\u0641\\u0626\\u06cc\\u0646 \\u0631\\u0627 \\u06a9\\u0645 \\u06a9\\u0646\\u06cc\\u062f\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(150,'pattern','recurring_pms','en','pattern / recurring_pms','{\"message\":\"Recurring PMS pattern detected in your data. You can manage symptoms with prior preparation.\",\"recommendation\":\"Reduce salt and caffeine intake a week before period\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(151,'pattern','severe_pain','fa','pattern / severe_pain','{\"message\":\"\\u062f\\u0631\\u062f\\u0647\\u0627\\u06cc \\u0634\\u062f\\u06cc\\u062f \\u0645\\u06a9\\u0631\\u0631 \\u0645\\u0634\\u0627\\u0647\\u062f\\u0647 \\u0634\\u062f\\u0647. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0627\\u062f\\u0627\\u0645\\u0647\\u060c \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0634\\u0648\\u0631\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"recommendation\":\"\\u067e\\u06cc\\u0634\\u0646\\u0647\\u0627\\u062f \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0628\\u0627 \\u0645\\u062a\\u062e\\u0635\\u0635 \\u0632\\u0646\\u0627\\u0646 \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u062f\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(152,'pattern','severe_pain','en','pattern / severe_pain','{\"message\":\"Recurring severe pain detected. Consult a doctor if it continues.\",\"recommendation\":\"It is recommended to talk to a gynecologist\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(153,'pattern','frequent_pain','fa','pattern / frequent_pain','{\"message\":\"\\u062f\\u0631\\u062f \\u062f\\u0631 \\u0628\\u06cc\\u0634 \\u0627\\u0632 \\u06f2\\u06f5\\u066a \\u0631\\u0648\\u0632\\u0647\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u0634\\u062f\\u0647. \\u0631\\u0627\\u0647\\u06a9\\u0627\\u0631\\u0647\\u0627\\u06cc \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u062f\\u0631\\u062f \\u0631\\u0627 \\u0627\\u0645\\u062a\\u062d\\u0627\\u0646 \\u06a9\\u0646\\u06cc\\u062f.\",\"recommendation\":\"\\u06cc\\u0648\\u06af\\u0627\\u060c \\u06a9\\u0645\\u067e\\u0631\\u0633 \\u06af\\u0631\\u0645 \\u0648 \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0636\\u062f\\u0627\\u0644\\u062a\\u0647\\u0627\\u0628\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u06a9\\u0645\\u06a9 \\u06a9\\u0646\\u062f\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(154,'pattern','frequent_pain','en','pattern / frequent_pain','{\"message\":\"Pain reported on more than 25% of days. Try pain management strategies.\",\"recommendation\":\"Yoga, warm compress and anti-inflammatory diet can help\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(155,'pattern','low_mood','fa','pattern / low_mood','{\"message\":\"\\u062e\\u0644\\u0642 \\u067e\\u0627\\u06cc\\u06cc\\u0646 \\u062f\\u0631 \\u0628\\u06cc\\u0634 \\u0627\\u0632 \\u06cc\\u06a9 \\u0633\\u0648\\u0645 \\u0631\\u0648\\u0632\\u0647\\u0627 \\u0645\\u0634\\u0627\\u0647\\u062f\\u0647 \\u0634\\u062f\\u0647. \\u0627\\u06af\\u0631 \\u0627\\u06cc\\u0646 \\u062d\\u0627\\u0644\\u062a \\u0627\\u062f\\u0627\\u0645\\u0647\\u200c\\u062f\\u0627\\u0631 \\u0627\\u0633\\u062a\\u060c \\u0628\\u0627 \\u0645\\u062a\\u062e\\u0635\\u0635 \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"recommendation\":\"\\u0648\\u0631\\u0632\\u0634 \\u0645\\u0646\\u0638\\u0645\\u060c \\u0646\\u0648\\u0631 \\u0622\\u0641\\u062a\\u0627\\u0628 \\u0648 \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0646\\u06cc\\u0627\\u0632 \\u0645\\u0634\\u0627\\u0648\\u0631\\u0647 \\u0631\\u0648\\u0627\\u0646\\u0634\\u0646\\u0627\\u0633\\u06cc\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(156,'pattern','low_mood','en','pattern / low_mood','{\"message\":\"Low mood detected on more than a third of days. If persistent, talk to a specialist.\",\"recommendation\":\"Regular exercise, sunlight and psychological counseling if needed\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
