(161,'pattern','poor_sleep','fa','pattern / poor_sleep','{\"message\":\"\\u06a9\\u06cc\\u0641\\u06cc\\u062a \\u062e\\u0648\\u0627\\u0628 \\u067e\\u0627\\u06cc\\u06cc\\u0646 \\u062f\\u0631 \\u0628\\u06cc\\u0634 \\u0627\\u0632 \\u06cc\\u06a9 \\u0633\\u0648\\u0645 \\u0631\\u0648\\u0632\\u0647\\u0627. \\u062e\\u0648\\u0627\\u0628 \\u0636\\u0639\\u06cc\\u0641 \\u0631\\u0648\\u06cc \\u0633\\u0644\\u0627\\u0645\\u062a \\u06a9\\u0644\\u06cc \\u062a\\u0623\\u062b\\u06cc\\u0631 \\u0645\\u06cc\\u200c\\u06af\\u0630\\u0627\\u0631\\u062f.\",\"recommendation\":\"\\u0628\\u0647\\u062f\\u0627\\u0634\\u062a \\u062e\\u0648\\u0627\\u0628 \\u0631\\u0627 \\u0631\\u0639\\u0627\\u06cc\\u062a \\u06a9\\u0646\\u06cc\\u062f: \\u0633\\u0627\\u0639\\u062a \\u062e\\u0648\\u0627\\u0628 \\u0645\\u0646\\u0638\\u0645\\u060c \\u0627\\u062a\\u0627\\u0642 \\u062a\\u0627\\u0631\\u06cc\\u06a9\\u060c \\u0628\\u062f\\u0648\\u0646 \\u06af\\u0648\\u0634\\u06cc \\u0642\\u0628\\u0644 \\u062e\\u0648\\u0627\\u0628\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(162,'pattern','poor_sleep','en','pattern / poor_sleep','{\"message\":\"Poor sleep quality on more than a third of days. Poor sleep affects overall health.\",\"recommendation\":\"Practice sleep hygiene: regular sleep schedule, dark room, no phone before bed\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(163,'pattern','chronic_fatigue','fa','pattern / chronic_fatigue','{\"message\":\"\\u0627\\u0646\\u0631\\u0698\\u06cc \\u067e\\u0627\\u06cc\\u06cc\\u0646 \\u0645\\u062f\\u0627\\u0648\\u0645 \\u0645\\u0634\\u0627\\u0647\\u062f\\u0647 \\u0634\\u062f\\u0647. \\u0627\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0646\\u0634\\u0627\\u0646\\u0647 \\u06a9\\u0645\\u200c\\u062e\\u0648\\u0646\\u06cc \\u06cc\\u0627 \\u0645\\u0634\\u06a9\\u0644\\u0627\\u062a \\u062a\\u06cc\\u0631\\u0648\\u0626\\u06cc\\u062f \\u0628\\u0627\\u0634\\u062f.\",\"recommendation\":\"\\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0648\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0622\\u0647\\u0646 \\u0648 \\u062a\\u06cc\\u0631\\u0648\\u0626\\u06cc\\u062f \\u062a\\u0648\\u0635\\u06cc\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(164,'pattern','chronic_fatigue','en','pattern / chronic_fatigue','{\"message\":\"Persistent low energy detected. This could indicate anemia or thyroid issues.\",\"recommendation\":\"Blood test for iron and thyroid is recommended\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(165,'pattern','increasing_nausea','fa','pattern / increasing_nausea','{\"message\":\"\\u062a\\u0647\\u0648\\u0639 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0627\\u0633\\u062a. \\u0627\\u06cc\\u0646 \\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06f8-\\u06f1\\u06f2 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a \\u0648 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0628\\u0639\\u062f\\u0627\\u064b \\u06a9\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"recommendation\":\"\\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0648 \\u0645\\u06a9\\u0631\\u0631\\u060c \\u0632\\u0646\\u062c\\u0628\\u06cc\\u0644 \\u0648 \\u0648\\u06cc\\u062a\\u0627\\u0645\\u06cc\\u0646 B6 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u06a9\\u0645\\u06a9 \\u06a9\\u0646\\u062f\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(166,'pattern','increasing_nausea','en','pattern / increasing_nausea','{\"message\":\"Nausea is increasing. This is normal in weeks 8-12 and usually decreases later.\",\"recommendation\":\"Small frequent meals, ginger and vitamin B6 can help\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(167,'pattern','improving_symptoms','fa','pattern / improving_symptoms','{\"message\":\"\\u0639\\u0644\\u0627\\u0626\\u0645 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0628\\u0647\\u0628\\u0648\\u062f \\u0647\\u0633\\u062a\\u0646\\u062f! \\u0627\\u06cc\\u0646 \\u0646\\u0634\\u0627\\u0646\\u0647 \\u0648\\u0631\\u0648\\u062f \\u0628\\u0647 \\u062f\\u0648\\u0631\\u0627\\u0646 \\u0637\\u0644\\u0627\\u06cc\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u0633\\u062a.\",\"recommendation\":\"\\u0627\\u0632 \\u0627\\u06cc\\u0646 \\u062f\\u0648\\u0631\\u0647 \\u0628\\u0631\\u0627\\u06cc \\u0648\\u0631\\u0632\\u0634 \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0648 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0644\\u0630\\u062a\\u200c\\u0628\\u062e\\u0634 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(168,'pattern','improving_symptoms','en','pattern / improving_symptoms','{\"message\":\"Symptoms are improving! This is a sign of entering the golden period of pregnancy.\",\"recommendation\":\"Use this period for gentle exercise and enjoyable activities\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(169,'bmi_message','underweight','fa','bmi_message / underweight','{\"message\":\"\\u0628\\u0631 \\u0627\\u0633\\u0627\\u0633 \\u0642\\u062f \\u0648 \\u0648\\u0632\\u0646 \\u0648\\u0627\\u0631\\u062f \\u0634\\u062f\\u0647\\u060c \\u062f\\u0631 \\u0645\\u062d\\u062f\\u0648\\u062f\\u0647 \\u06a9\\u0645\\u200c\\u0648\\u0632\\u0646 \\u0642\\u0631\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u06cc. \\u0627\\u06af\\u0631 \\u0627\\u06cc\\u0646 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0628\\u0631\\u0627\\u06cc \\u0645\\u062f\\u062a \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u062f\\u060c \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0631\\u0648\\u06cc \\u0627\\u0646\\u0631\\u0698\\u06cc\\u060c \\u062e\\u0644\\u0642 \\u0648 \\u0633\\u06cc\\u06a9\\u0644 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc\\u200c\\u0627\\u062a \\u0627\\u062b\\u0631 \\u0628\\u06af\\u0630\\u0627\\u0631\\u062f. \\u0627\\u06af\\u0631 \\u0646\\u06af\\u0631\\u0627\\u0646 \\u0647\\u0633\\u062a\\u06cc\\u060c \\u0628\\u0647\\u062a\\u0631 \\u0627\\u0633\\u062a \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u06cc\\u0627 \\u06a9\\u0627\\u0631\\u0634\\u0646\\u0627\\u0633 \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646\\u06cc.\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(170,'bmi_message','underweight','en','bmi_message / underweight','{\"message\":\"Based on the height and weight you entered, you fall in the underweight range. If this continues for a long time, it can affect your energy, mood, and menstrual cycle. If you are concerned, it is best to talk to a doctor or a nutrition specialist.\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(171,'bmi_message','normal','fa','bmi_message / normal','{\"message\":\"\\u0628\\u0631 \\u0627\\u0633\\u0627\\u0633 \\u0642\\u062f \\u0648 \\u0648\\u0632\\u0646 \\u0648\\u0627\\u0631\\u062f \\u0634\\u062f\\u0647\\u060c \\u062f\\u0631 \\u0645\\u062d\\u062f\\u0648\\u062f\\u0647\\u200c\\u06cc \\u0648\\u0632\\u0646\\u06cc \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0642\\u0631\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u06cc. \\u0627\\u06cc\\u0646 \\u0645\\u062d\\u062f\\u0648\\u062f\\u0647 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0628\\u0631\\u0627\\u06cc \\u0633\\u0644\\u0627\\u0645\\u062a \\u0639\\u0645\\u0648\\u0645\\u06cc \\u0648 \\u0633\\u06cc\\u06a9\\u0644 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc \\u0645\\u0646\\u0627\\u0633\\u0628 \\u0627\\u0633\\u062a. Ritme \\u062a\\u0644\\u0627\\u0634 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u0628\\u0647 \\u062d\\u0641\\u0638 \\u0627\\u06cc\\u0646 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u06a9\\u0645\\u06a9 \\u06a9\\u0646\\u062f.\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(172,'bmi_message','normal','en','bmi_message / normal','{\"message\":\"Based on the height and weight you entered, you are in the normal weight range. This range is usually good for overall health and your menstrual cycle. Ritme aims to help you maintain it.\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(173,'bmi_message','overweight','fa','bmi_message / overweight','{\"message\":\"\\u0628\\u0631 \\u0627\\u0633\\u0627\\u0633 \\u0642\\u062f \\u0648 \\u0648\\u0632\\u0646 \\u0648\\u0627\\u0631\\u062f \\u0634\\u062f\\u0647\\u060c \\u062f\\u0631 \\u0645\\u062d\\u062f\\u0648\\u062f\\u0647\\u200c\\u06cc \\u0627\\u0636\\u0627\\u0641\\u0647\\u200c\\u0648\\u0632\\u0646 \\u0642\\u0631\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u06cc. \\u0627\\u06cc\\u0646 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u062f\\u0631 \\u0628\\u0639\\u0636\\u06cc \\u0627\\u0641\\u0631\\u0627\\u062f \\u0631\\u0648\\u06cc \\u0627\\u0646\\u0631\\u0698\\u06cc\\u060c \\u062e\\u0648\\u0627\\u0628 \\u0648 \\u0633\\u06cc\\u06a9\\u0644 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc (\\u0628\\u0647\\u200c\\u062e\\u0635\\u0648\\u0635 \\u062f\\u0631 PCOS) \\u0627\\u062b\\u0631 \\u0628\\u06af\\u0630\\u0627\\u0631\\u062f. \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u06a9\\u0648\\u0686\\u06a9 \\u0648 \\u067e\\u0627\\u06cc\\u062f\\u0627\\u0631 \\u062f\\u0631 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0648 \\u062a\\u063a\\u0630\\u06cc\\u0647\\u060c \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0627\\u0632 \\u0631\\u0698\\u06cc\\u0645\\u200c\\u0647\\u0627\\u06cc \\u0633\\u062e\\u062a \\u0628\\u0647 \\u0633\\u0644\\u0627\\u0645\\u062a\\u062a \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f.\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(174,'bmi_message','overweight','en','bmi_message / overweight','{\"message\":\"Based on the height and weight you entered, you fall in the overweight range. In some people this can affect energy, sleep, and the menstrual cycle (especially with PCOS). Small, sustainable changes in activity and nutrition help your health more than strict diets.\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(175,'bmi_message','obese','fa','bmi_message / obese','{\"message\":\"\\u0628\\u0631 \\u0627\\u0633\\u0627\\u0633 \\u0642\\u062f \\u0648 \\u0648\\u0632\\u0646 \\u0648\\u0627\\u0631\\u062f \\u0634\\u062f\\u0647\\u060c \\u062f\\u0631 \\u0645\\u062d\\u062f\\u0648\\u062f\\u0647\\u200c\\u06cc \\u0686\\u0627\\u0642\\u06cc \\u0642\\u0631\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u06cc. \\u0627\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u062f\\u0631 \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc\\u200c\\u0645\\u062f\\u062a \\u0631\\u0648\\u06cc \\u0633\\u0644\\u0627\\u0645\\u062a \\u0642\\u0644\\u0628\\u060c \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0642\\u0646\\u062f \\u0648 \\u0633\\u06cc\\u06a9\\u0644 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc \\u0627\\u062b\\u0631 \\u0628\\u06af\\u0630\\u0627\\u0631\\u062f. \\u0627\\u06af\\u0631 \\u0627\\u0645\\u06a9\\u0627\\u0646\\u0634 \\u0631\\u0627 \\u062f\\u0627\\u0631\\u06cc\\u060c \\u0635\\u062d\\u0628\\u062a \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u06cc\\u0627 \\u06a9\\u0627\\u0631\\u0634\\u0646\\u0627\\u0633 \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u062e\\u06cc\\u0644\\u06cc \\u06a9\\u0645\\u06a9\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0628\\u0627\\u0634\\u062f. \\u062f\\u0631 Ritme \\u0633\\u0639\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u06cc\\u0645 \\u0628\\u0627 \\u062a\\u0648\\u0635\\u06cc\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0642\\u0627\\u0628\\u0644\\u200c\\u0627\\u062c\\u0631\\u0627\\u060c \\u0628\\u0647 \\u0631\\u0648\\u0646\\u062f \\u0633\\u0644\\u0627\\u0645\\u062a\\u062a \\u06a9\\u0645\\u06a9 \\u06a9\\u0646\\u06cc\\u0645.\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(176,'bmi_message','obese','en','bmi_message / obese','{\"message\":\"Based on the height and weight you entered, you fall in the obesity range. Over the long term this can affect heart health, blood pressure, blood sugar, and the menstrual cycle. If possible, talking to a doctor or a nutrition specialist can be very helpful. At Ritme we try to support your health journey with small, doable recommendations.\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00');
