(1,'menstruation','{\"fa\":\"\\u0634\\u0631\\u0648\\u0639 \\u067e\\u0631\\u06cc\\u0648\\u062f \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0628\\u0627 \\u0627\\u0641\\u062a \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0648 \\u062f\\u0631\\u062f\\u0647\\u0627\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u06cc\\u0627 \\u0645\\u062a\\u0648\\u0633\\u0637 \\u062f\\u0631 \\u0646\\u0627\\u062d\\u06cc\\u0647 \\u0632\\u06cc\\u0631 \\u0634\\u06a9\\u0645 \\u0648 \\u06a9\\u0645\\u0631 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0627\\u0633\\u062a. \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a \\u06a9\\u0647 \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0631\\u0648\\u0632\\u0647\\u0627 \\u062d\\u0633 \\u06a9\\u0646\\u06cc \\u0646\\u06cc\\u0627\\u0632 \\u0628\\u0647 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0631\\u06cc\\u061b \\u0628\\u062f\\u0646 \\u062a\\u0648 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u06cc\\u06a9 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0628\\u06cc\\u0648\\u0644\\u0648\\u0698\\u06cc\\u06a9 \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a. \\u0627\\u06af\\u0631 \\u062f\\u0631\\u062f\\u0647\\u0627 \\u062a\\u0627 \\u062d\\u062f\\u06cc \\u0627\\u0633\\u062a \\u06a9\\u0647 \\u0632\\u0646\\u062f\\u06af\\u06cc \\u0639\\u0627\\u062f\\u06cc\\u200c\\u0627\\u062a \\u0631\\u0627 \\u0645\\u062e\\u062a\\u0644 \\u06a9\\u0631\\u062f\\u0647\\u060c \\u0646\\u06af\\u0631\\u0627\\u0646 \\u0646\\u0628\\u0627\\u0634 \\u0627\\u0645\\u0627 \\u062d\\u062a\\u0645\\u0627\\u064b \\u0628\\u0647 \\u0622\\u0646 \\u062a\\u0648\\u062c\\u0647 \\u06a9\\u0646.\",\"en\":null}','{\"fa\":\"\\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0631\\u0648\\u0632\\u0647\\u0627 \\u062e\\u0648\\u0646\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u062a\\u0646\\u0647\\u0627 \\u0686\\u06cc\\u0632\\u06cc \\u0627\\u0633\\u062a \\u06a9\\u0647 \\u0645\\u06cc\\u200c\\u0628\\u06cc\\u0646\\u06cc. \\u062a\\u0631\\u0634\\u062d\\u0627\\u062a 