INSERT INTO `recommendations` VALUES
(1,'menstruation.hydration','hydration',NULL,'{\"fa\":\"\\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f \\u0648 \\u0647\\u06cc\\u062f\\u0631\\u0627\\u062a\\u0647 \\u0628\\u0645\\u0627\\u0646\\u06cc\\u062f.\",\"en\":\"Stay hydrated and drink plenty of water.\"}','menstruation',NULL,NULL,1,10,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(2,'menstruation.warmth','warmth',NULL,'{\"fa\":\"\\u06a9\\u0645\\u067e\\u0631\\u0633 \\u06af\\u0631\\u0645 \\u0631\\u0648\\u06cc \\u0634\\u06a9\\u0645 \\u0642\\u0631\\u0627\\u0631 \\u062f\\u0647\\u06cc\\u062f \\u062a\\u0627 \\u062f\\u0631\\u062f\\u0647\\u0627 \\u06a9\\u0627\\u0647\\u0634 \\u06cc\\u0627\\u0628\\u062f.\",\"en\":\"Apply a warm compress to your lower abdomen to relieve cramps.\"}','menstruation',NULL,NULL,1,20,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(3,'menstruation.rest','rest',NULL,'{\"fa\":\"\\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0627\\u062c\\u062a\\u0646\\u0627\\u0628 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Get enough rest and avoid strenuous activities.\"}','menstruation',NULL,NULL,1,30,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(4,'menstruation.nutrition','nutrition',NULL,'{\"fa\":\"\\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u063a\\u0646\\u06cc \\u0627\\u0632 \\u0622\\u0647\\u0646 \\u0645\\u062b\\u0644 \\u0627\\u0633\\u0641\\u0646\\u0627\\u062c \\u0648 \\u06af\\u0648\\u0634\\u062a \\u0642\\u0631\\u0645\\u0632 \\u0628\\u062e\\u0648\\u0631\\u06cc\\u062f.\",\"en\":\"Eat iron-rich foods like spinach and red meat.\"}','menstruation',NULL,NULL,1,40,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(5,'follicular.energy','energy',NULL,'{\"fa\":\"\\u0633\\u0637\\u062d \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0634\\u0645\\u0627 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0627\\u0633\\u062a. \\u0632\\u0645\\u0627\\u0646 \\u0645\\u0646\\u0627\\u0633\\u0628\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u067e\\u0631\\u0648\\u0698\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062c\\u062f\\u06cc\\u062f!\",\"en\":\"Your energy levels are rising. Great time for new projects!\"}','follicular',NULL,NULL,1,50,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(6,'follicular.exercise','exercise',NULL,'{\"fa\":\"\\u0632\\u0645\\u0627\\u0646 \\u0645\\u0646\\u0627\\u0633\\u0628\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0648\\u0631\\u0632\\u0634\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0627\\u0633\\u062a.\",\"en\":\"Perfect time for high-intensity workouts.\"}','follicular',NULL,NULL,1,60,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(7,'follicular.nutrition','nutrition',NULL,'{\"fa\":\"\\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0633\\u0628\\u0632\\u06cc\\u062c\\u0627\\u062a \\u062a\\u0627\\u0632\\u0647 \\u0628\\u062e\\u0648\\u0631\\u06cc\\u062f \\u062a\\u0627 \\u0630\\u062e\\u06cc\\u0631\\u0647 \\u0627\\u0646\\u0631\\u0698\\u06cc\\u200c\\u062a\\u0627\\u0646 \\u062f\\u0648\\u0628\\u0627\\u0631\\u0647 \\u067e\\u0631 \\u0634\\u0648\\u062f.\",\"en\":\"Add protein and fresh vegetables to rebuild your energy stores.\"}','follicular',NULL,NULL,1,70,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(8,'follicular.mental_health','mental_health',NULL,'{\"fa\":\"\\u0641\\u0631\\u0635\\u062a \\u062e\\u0648\\u0628\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u0648 \\u06cc\\u0627\\u062f\\u06af\\u06cc\\u0631\\u06cc \\u0686\\u06cc\\u0632\\u0647\\u0627\\u06cc \\u062a\\u0627\\u0632\\u0647 \\u0627\\u0633\\u062a.\",\"en\":\"A good window for planning and learning something new.\"}','follicular',NULL,NULL,1,80,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(9,'ovulation.fertility','fertility',NULL,'{\"fa\":\"\\u0631\\u0648\\u0632\\u0647\\u0627\\u06cc \\u0627\\u0648\\u062c \\u0628\\u0627\\u0631\\u0648\\u0631\\u06cc. \\u0627\\u06af\\u0631 \\u0642\\u0635\\u062f \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0627\\u0631\\u06cc\\u062f\\u060c \\u0628\\u0647\\u062a\\u0631\\u06cc\\u0646 \\u0632\\u0645\\u0627\\u0646 \\u0627\\u0633\\u062a.\",\"en\":\"Peak fertility days. If trying to conceive, this is the best time.\"}','ovulation',NULL,NULL,1,90,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(10,'ovulation.energy','energy',NULL,'{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f \\u0628\\u0647 \\u0646\\u0641\\u0633 \\u0648 \\u0627\\u062c\\u062a\\u0645\\u0627\\u0639\\u06cc \\u0628\\u0648\\u062f\\u0646 \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"You may feel more confident and social.\"}','ovulation',NULL,NULL,1,100,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(11,'ovulation.hydration','hydration',NULL,'{\"fa\":\"\\u0645\\u0631\\u062a\\u0628 \\u0622\\u0628 \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f\\u061b \\u0647\\u06cc\\u062f\\u0631\\u0627\\u062a\\u0647 \\u0628\\u0648\\u062f\\u0646 \\u0628\\u0647 \\u06a9\\u06cc\\u0641\\u06cc\\u062a \\u062a\\u0631\\u0634\\u062d\\u0627\\u062a \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"Drink water regularly \\u2014 hydration supports cervical fluid.\"}','ovulation',NULL,NULL,1,110,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(12,'ovulation.sleep','sleep',NULL,'{\"fa\":\"\\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u062e\\u0648\\u0627\\u0628 \\u0645\\u0646\\u0638\\u0645\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f \\u062a\\u0627 \\u062a\\u0639\\u0627\\u062f\\u0644 \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u06cc \\u062d\\u0641\\u0638 \\u0634\\u0648\\u062f.\",\"en\":\"Keep a steady sleep schedule to support hormone balance.\"}','ovulation',NULL,NULL,1,120,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(13,'luteal.nutrition','nutrition',NULL,'{\"fa\":\"\\u0631\\u0648\\u06cc \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u063a\\u0646\\u06cc \\u0627\\u0632 \\u0645\\u0646\\u06cc\\u0632\\u06cc\\u0645 \\u0648 \\u0648\\u06cc\\u062a\\u0627\\u0645\\u06cc\\u0646 B6 \\u062a\\u0645\\u0631\\u06a9\\u0632 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Focus on foods rich in magnesium and vitamin B6.\"}','luteal','[\"early_luteal\",\"mid_luteal\"]',NULL,1,130,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(14,'luteal.exercise','exercise',NULL,'{\"fa\":\"\\u0628\\u0647 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u0645\\u0644\\u0627\\u06cc\\u0645\\u200c\\u062a\\u0631 \\u0645\\u062b\\u0644 \\u06cc\\u0648\\u06af\\u0627\\u060c \\u067e\\u06cc\\u0644\\u0627\\u062a\\u0633 \\u06cc\\u0627 \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0631\\u0648 \\u0628\\u06cc\\u0627\\u0648\\u0631\\u06cc\\u062f.\",\"en\":\"Switch to gentler movement like yoga, pilates or walking.\"}','luteal','[\"early_luteal\",\"mid_luteal\"]',NULL,1,140,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(15,'luteal.sleep','sleep',NULL,'{\"fa\":\"\\u06a9\\u0645\\u06cc \\u0632\\u0648\\u062f\\u062a\\u0631 \\u0628\\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f\\u061b \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0641\\u0627\\u0632 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u06a9\\u0645\\u200c\\u06a9\\u0645 \\u0627\\u0641\\u062a \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"Go to bed a little earlier \\u2014 energy dips in this phase.\"}','luteal','[\"early_luteal\",\"mid_luteal\"]',NULL,1,150,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(16,'luteal.mental_health','mental_health',NULL,'{\"fa\":\"\\u0632\\u0645\\u0627\\u0646 \\u062e\\u0648\\u0628\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0645\\u0627\\u0645\\u200c\\u06a9\\u0631\\u062f\\u0646 \\u06a9\\u0627\\u0631\\u0647\\u0627\\u06cc \\u0646\\u06cc\\u0645\\u0647\\u200c\\u062a\\u0645\\u0627\\u0645 \\u0627\\u0633\\u062a \\u062a\\u0627 \\u0634\\u0631\\u0648\\u0639 \\u06a9\\u0627\\u0631\\u0647\\u0627\\u06cc \\u062c\\u062f\\u06cc\\u062f.\",\"en\":\"A good time to finish what you started rather than begin new things.\"}','luteal','[\"early_luteal\",\"mid_luteal\"]',NULL,1,160,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(17,'luteal.pms','pms',NULL,'{\"fa\":\"\\u0639\\u0644\\u0627\\u0626\\u0645 PMS \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0638\\u0627\\u0647\\u0631 \\u0634\\u0648\\u0646\\u062f. \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u062e\\u0648\\u062f \\u0648 \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0631\\u0627 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"PMS symptoms may appear. Practice self-care and relaxation.\"}','luteal','[\"late_luteal\",\"pms_possible\"]',NULL,1,170,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(18,'luteal.pms_nutrition','nutrition',NULL,'{\"fa\":\"\\u0645\\u0635\\u0631\\u0641 \\u0646\\u0645\\u06a9 \\u0648 \\u06a9\\u0627\\u0641\\u0626\\u06cc\\u0646 \\u0631\\u0627 \\u06a9\\u0627\\u0647\\u0634 \\u062f\\u0647\\u06cc\\u062f \\u062a\\u0627 \\u0646\\u0641\\u062e \\u06a9\\u0645 \\u0634\\u0648\\u062f.\",\"en\":\"Reduce salt and caffeine intake to minimize bloating.\"}','luteal','[\"late_luteal\",\"pms_possible\"]',NULL,1,180,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(19,'luteal.pms_mood','mood',NULL,'{\"fa\":\"\\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0627\\u06af\\u0631 \\u0627\\u062d\\u0633\\u0627\\u0633 \\u062a\\u062d\\u0631\\u06cc\\u06a9\\u200c\\u067e\\u0630\\u06cc\\u0631\\u06cc \\u062f\\u0627\\u0631\\u06cc\\u062f \\u062a\\u0646\\u0641\\u0633 \\u0639\\u0645\\u06cc\\u0642 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Take breaks and practice deep breathing if feeling irritable.\"}','luteal','[\"late_luteal\",\"pms_possible\"]',NULL,1,190,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(20,'symptom.headache','pain_relief',NULL,'{\"fa\":\"\\u0628\\u0631\\u0627\\u06cc \\u0633\\u0631\\u062f\\u0631\\u062f: \\u062f\\u0631 \\u0627\\u062a\\u0627\\u0642 \\u062a\\u0627\\u0631\\u06cc\\u06a9 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0622\\u0628 \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f.\",\"en\":\"For headaches: rest in a dark room and stay hydrated.\"}',NULL,NULL,'headache',1,200,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(21,'symptom.cramps','pain_relief',NULL,'{\"fa\":\"\\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0631\\u0627\\u0645\\u067e: \\u062d\\u0645\\u0627\\u0645 \\u06af\\u0631\\u0645 \\u06cc\\u0627 \\u067e\\u062f \\u06af\\u0631\\u0645\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0627\\u0645\\u062a\\u062d\\u0627\\u0646 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"For cramps: try a warm bath or heating pad.\"}',NULL,NULL,'cramps',1,210,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(22,'symptom.poor_sleep','sleep',NULL,'{\"fa\":\"\\u0633\\u0639\\u06cc \\u06a9\\u0646\\u06cc\\u062f \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u062e\\u0648\\u0627\\u0628 \\u0645\\u0646\\u0638\\u0645 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f \\u0648 \\u0642\\u0628\\u0644 \\u0627\\u0632 \\u062e\\u0648\\u0627\\u0628 \\u0627\\u0632 \\u0635\\u0641\\u062d\\u0647 \\u0646\\u0645\\u0627\\u06cc\\u0634 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u0646\\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Try to maintain a regular sleep schedule and avoid screens before bed.\"}',NULL,NULL,'poor_sleep',1,220,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(23,'symptom.low_mood','mental_health',NULL,'{\"fa\":\"\\u0648\\u0642\\u062a\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0648\\u0631\\u062f \\u0639\\u0644\\u0627\\u0642\\u0647\\u200c\\u062a\\u0627\\u0646 \\u0628\\u06af\\u0630\\u0627\\u0631\\u06cc\\u062f. \\u0648\\u0631\\u0632\\u0634 \\u0633\\u0628\\u06a9 \\u06cc\\u0627 \\u0645\\u062f\\u06cc\\u062a\\u06cc\\u0634\\u0646 \\u0631\\u0627 \\u062f\\u0631 \\u0646\\u0638\\u0631 \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f.\",\"en\":\"Take time for activities you enjoy. Consider light exercise or meditation.\"}',NULL,NULL,'low_mood',1,230,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(24,'symptom.bloating','digestion',NULL,'{\"fa\":\"\\u0645\\u0635\\u0631\\u0641 \\u0646\\u0645\\u06a9 \\u0631\\u0627 \\u06a9\\u0645 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0648 \\u0645\\u06a9\\u0631\\u0631 \\u0628\\u062e\\u0648\\u0631\\u06cc\\u062f.\",\"en\":\"Reduce salt intake and eat smaller, frequent meals.\"}',NULL,NULL,'bloating',1,240,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(25,'symptom.fatigue','energy',NULL,'{\"fa\":\"\\u0628\\u0647 \\u0628\\u062f\\u0646\\u062a\\u0627\\u0646 \\u06af\\u0648\\u0634 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u062a\\u0627\\u0647 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0631\\u0627 \\u0627\\u0648\\u0644\\u0648\\u06cc\\u062a \\u0642\\u0631\\u0627\\u0631 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Listen to your body. Take short breaks and prioritize rest.\"}',NULL,NULL,'fatigue',1,250,'2026-09-23 09:00:00','2026-09-23 09:00:00');
