(1,'log_bbt','{\"fa\":\"\\u062b\\u0628\\u062a \\u062f\\u0645\\u0627\\u06cc \\u0628\\u062f\\u0646\",\"en\":\"Log body temperature\"}','{\"fa\":\"\\u062f\\u0645\\u0627\\u06cc \\u067e\\u0627\\u06cc\\u0647 \\u0628\\u062f\\u0646\\u062a \\u0631\\u0627 \\u0647\\u0631 \\u0631\\u0648\\u0632 \\u0635\\u0628\\u062d \\u062b\\u0628\\u062a \\u06a9\\u0646\",\"en\":\"Record your basal body temperature each morning\"}','tracking',NULL,NULL,1,1,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(2,'drink_water','{\"fa\":\"\\u0646\\u0648\\u0634\\u06cc\\u062f\\u0646 \\u06f8 \\u0644\\u06cc\\u0648\\u0627\\u0646 \\u0622\\u0628\",\"en\":\"Drink 8 glasses of water\"}','{\"fa\":\"\\u062f\\u0631 \\u0637\\u0648\\u0644 \\u0631\\u0648\\u0632 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06a9\\u0627\\u0641\\u06cc \\u0622\\u0628 \\u0628\\u0646\\u0648\\u0634\",\"en\":\"Stay hydrated throughout the day\"}','hydration',NULL,NULL,1,2,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(3,'vitamin_d','{\"fa\":\"\\u0645\\u0635\\u0631\\u0641 \\u0648\\u06cc\\u062a\\u0627\\u0645\\u06cc\\u0646 D\",\"en\":\"Take vitamin D\"}','{\"fa\":\"\\u0645\\u06a9\\u0645\\u0644 \\u0648\\u06cc\\u062a\\u0627\\u0645\\u06cc\\u0646 D \\u062e\\u0648\\u062f \\u0631\\u0627 \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\",\"en\":\"Take your vitamin D supplement\"}','supplement',NULL,NULL,1,3,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(4,'walk_30','{\"fa\":\"\\u06f3\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\",\"en\":\"30 minutes walking\"}','{\"fa\":\"\\u06cc\\u06a9 \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0633\\u0628\\u06a9 \\u06f3\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647\\u200c\\u0627\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\",\"en\":\"Take a light 30-minute walk\"}','exercise',NULL,NULL,1,4,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
